  8→/**
  9→ * Single criterion with Given/When/Then structure
 10→ */
 11→export interface Criterion {
 12→  given: string;
 13→  when: string;
 14→  then: string;
 15→}
 16→
 17→/**
 18→ * Output interface for acceptance criteria
 19→ */
 20→export interface AcceptanceCriteria {
 21→  formatted: string;
 22→  criteriaCount: number;
 23→}
 24→
 25→type AcceptanceCriteriaInput = {
 26→  story: string;
 27→  criteria: Criterion[];
 28→};
 29→
 30→/**
 31→ * Validates a single criterion object
 32→ */
 33→function validateCriterion(criterion: unknown, index: number): criterion is Criterion {
 34→  if (!criterion || typeof criterion !== 'object') {
 35→    throw new Error(`Criterion at index ${index} must be an object`);
 36→  }
 37→
 38→  const c = criterion as Record<string, unknown>;
 39→
 40→  if (!c.given || typeof c.given !== 'string' || c.given.trim().length === 0) {
 41→    throw new Error(`Criterion at index ${index} must have a non-empty 'given' property`);
 42→  }
 43→
 44→  if (!c.when || typeof c.when !== 'string' || c.when.trim().length === 0) {
 45→    throw new Error(`Criterion at index ${index} must have a non-empty 'when' property`);
 46→  }
 47→
 48→  if (!c.then || typeof c.then !== 'string' || c.then.trim().length === 0) {
 49→    throw new Error(`Criterion at index ${index} must have a non-empty 'then' property`);
 50→  }
 51→
 52→  return true;
 53→}
 54→
 55→/**
 56→ * Formats a single criterion in Gherkin style
 57→ */
 58→function formatCriterion(criterion: Criterion, index: number): string {
 59→  const scenarioNumber = index + 1;
 60→  const scenarioTitle = `Scenario ${scenarioNumber}`;
 61→
 62→  return `### ${scenarioTitle}
 63→
 64→**Given** ${criterion.given}
 65→**When** ${criterion.when}
 66→**Then** ${criterion.then}`;
 67→}
 68→
 69→/**
 70→ * Extracts a short title from the story for the heading
 71→ */
 72→function extractTitle(story: string): string {
 73→  // Take first sentence or first 80 characters
 74→  const firstSentence = story.split(/[.!?]/)[0]?.trim();
 75→  if (!firstSentence) return 'User Story';
 76→
 77→  if (firstSentence.length <= 80) {
 78→    return firstSentence;
 79→  }
 80→
 81→  return `${firstSentence.substring(0, 77)}...`;
 82→}
