108→            },
109→            when: {
110→              type: 'string',
111→              description: 'The action or event that occurs',
112→            },
113→            then: {
114→              type: 'string',
115→              description: 'The expected outcome or result',
116→            },
117→          },
118→          required: ['given', 'when', 'then'],
119→        },
120→      },
121→    },
122→    required: ['story', 'criteria'],
123→    additionalProperties: false,
124→  }),
125→  async execute({ story, criteria }): Promise<AcceptanceCriteria> {
126→    // Validate story
127→    if (!story || typeof story !== 'string' || story.trim().length === 0) {
128→      throw new Error('Story is required and must be a non-empty string');
129→    }
130→
131→    // Validate criteria array
132→    if (!Array.isArray(criteria)) {
133→      throw new Error('Criteria must be an array');
134→    }
135→
136→    if (criteria.length === 0) {
137→      throw new Error('Criteria array must contain at least one criterion');
138→    }
139→
140→    if (criteria.length > 20) {
141→      throw new Error('Criteria array cannot contain more than 20 criteria');
142→    }
143→
144→    // Validate each criterion
145→    for (let i = 0; i < criteria.length; i++) {
146→      validateCriterion(criteria[i], i);
147→    }
148→
149→    // Format the acceptance criteria
150→    const title = extractTitle(story);
151→    const formattedCriteria = criteria.map((c, i) => formatCriterion(c, i)).join('\n\n');
152→
153→    const formatted = `# Acceptance Criteria
154→
155→## ${title}
156→
157→${story}
158→
159→---
160→
161→## Scenarios
162→
163→${formattedCriteria}
164→`;
165→
166→    return {
167→      formatted,
168→      criteriaCount: criteria.length,
169→    };
170→  },
171→});
