    \"packageName\": \"@tpmjs/official-sandbox-shell\",
    \"name\": \"$tool_name\",
    \"version\": \"0.1.0\",
    \"params\": $params,
    \"sessionId\": \"$SESSION_ID\"
  }"
}
```

Usage: `./test-sandbox.sh http://localhost:3002 [api-key]`

---

### 8. **git-credential-env** (`templates/agent-sandbox/git-credential-env`)

Simple shell script for Git credential helper:

```sh
#!/bin/sh
# Git credential helper that reads GITHUB_TOKEN from the environment.
# Configured via git config --system credential.helper.
if [ "$1" = "get" ]; then
  if [ -n "$GITHUB_TOKEN" ]; then
    echo "protocol=https"
    echo "host=github.com"
    echo "username=x-access-token"
    echo "password=$GITHUB_TOKEN"
  fi
fi
```

**Purpose**: Allows git to clone private repos by reading `GITHUB_TOKEN` env var instead of prompting for credentials.

