271→/**
272→ * Destroy a sandbox session (fire-and-forget safe)
273→ * Returns gracefully even if the session doesn't exist.
274→ */
275→export async function destroySandboxSession(
276→  url: string,
277→  apiKey: string | undefined,
278→  sessionId: string
279→): Promise<DestroySessionResponse> {
280→  const headers: Record<string, string> = {};
281→  if (apiKey) {
282→    headers.Authorization = `Bearer ${apiKey}`;
283→  }
284→
285→  try {
286→    const controller = new AbortController();
287→    const timeoutId = setTimeout(() => controller.abort(), 10000);
288→
289→    const response = await fetch(`${url}/sessions/${encodeURIComponent(sessionId)}`, {
290→      method: 'DELETE',
291→      headers,
292→      signal: controller.signal,
293→    });
294→
295→    clearTimeout(timeoutId);
296→
297→    if (!response.ok && response.status !== 404) {
298→      return { sessionId, destroyed: false };
299→    }
300→
301→    return (await response
302→      .json()
303→      .catch(() => ({ sessionId, destroyed: true }))) as DestroySessionResponse;
304→  } catch {
305→    // Fire-and-forget: don't throw on cleanup failures
306→    return { sessionId, destroyed: false };
307→  }
308→}
