544→/**
545→ * Verify a custom executor URL is valid and operational
546→ *
547→ * @param url - Executor URL to verify
548→ * @param apiKey - Optional API key for authentication
549→ * @returns Verification result
550→ */
551→export async function verifyExecutor(
552→  url: string,
553→  apiKey?: string
554→): Promise<{
555→  valid: boolean;
556→  healthCheck?: { healthy: boolean; response?: ExecutorHealthResponse };
557→  testExecution?: { success: boolean; executionTimeMs: number };
558→  errors: string[];
559→}> {
560→  const errors: string[] = [];
561→
562→  // Validate URL format
563→  try {
564→    const parsed = new URL(url);
565→    if (parsed.protocol !== 'https:' && process.env.NODE_ENV === 'production') {
566→      errors.push('Custom executor URL must use HTTPS in production');
567→    }
568→  } catch {
569→    errors.push('Invalid URL format');
570→    return { valid: false, errors };
571→  }
572→
573→  // Check health endpoint
574→  const healthResult = await checkExecutorHealth(url, apiKey);
575→  if (!healthResult.healthy) {
576→    errors.push(healthResult.error || 'Health check failed');
577→  }
578→
579→  // Test execution (only if health check passed)
580→  let testResult: { success: boolean; executionTimeMs: number } | undefined;
581→  if (healthResult.healthy) {
582→    const execResult = await testExecutor(url, apiKey);
583→    testResult = {
584→      success: execResult.success,
585→      executionTimeMs: execResult.executionTimeMs,
586→    };
587→    if (!execResult.success) {
588→      errors.push(execResult.error || 'Test execution failed');
589→    }
590→  }
591→
592→  return {
593→    valid: errors.length === 0,
594→    healthCheck: {
595→      healthy: healthResult.healthy,
596→      response: healthResult.response,
597→    },
598→    testExecution: testResult,
599→    errors,
600→  };
601→}
