486→// Default export
487→// ---------------------------------------------------------------------------
488→
489→export default { shellExec, readFile, writeFile, listFiles };
490→

  1→/**
  2→ * Agent Conversation Endpoint (Username/Slug-based version)
  3→ *
  4→ * POST: Send a message and stream the AI response
  5→ * GET: Retrieve conversation history
  6→ * DELETE: Delete a conversation
  7→ *
  8→ * This endpoint uses username and agent slug for public-friendly URLs.
  9→ * Example: /api/ajax/agents/tpmjs-discord/conversation/my-conv-1
 10→ *
 11→ * Authentication: Supports both session auth and TPMJS API key auth.
 12→ * Requires 'agent:chat' scope for API key access.
 13→ */
 14→
 15→import { Prisma, prisma } from '@tpmjs/db';
 16→import type { AIProvider } from '@tpmjs/types/agent';
 17→import { SendMessageSchema } from '@tpmjs/types/agent';
 18→import type { LanguageModel, ModelMessage } from 'ai';
 19→import { type NextRequest, NextResponse } from 'next/server';
 20→import { decryptApiKey } from '@/lib/crypto/api-keys';
 21→import { logActivity } from '~/lib/activity';
 22→import { authenticateRequest, hasScope } from '~/lib/api-keys/middleware';
 23→import { trackUsage } from '~/lib/api-keys/usage';
 24→import { checkRateLimit, type RateLimitConfig } from '~/lib/rate-limit';
 25→import { trackExecution } from '~/lib/tracking/executions';
 26→
 27→/**
 28→ * Rate limit for chat messages: 30 requests per minute
 29→ * This is stricter than default because chat involves expensive LLM calls
 30→ */
 31→const CHAT_RATE_LIMIT: RateLimitConfig = {
 32→  limit: 30,
 33→  windowSeconds: 60,
 34→};
 35→
 36→export const runtime = 'nodejs';
 37→export const dynamic = 'force-dynamic';
 38→export const maxDuration = 300; // 5 minutes for long agentic runs
 39→
 40→type RouteContext = {
 41→  params: Promise<{ username: string; agentSlug: string; conversationId: string }>;
 42→};
 43→
 44→/**
 45→ * Get AI provider SDK based on provider type
 46→ */
 47→async function getProviderModel(
 48→  provider: AIProvider,
 49→  modelId: string,
 50→  apiKey: string
 51→): Promise<LanguageModel> {
 52→  switch (provider) {
 53→    case 'OPENAI': {
 54→      const { createOpenAI } = await import('@ai-sdk/openai');
 55→      return createOpenAI({ apiKey })(modelId);
 56→    }
 57→    case 'ANTHROPIC': {
 58→      const { createAnthropic } = await import('@ai-sdk/anthropic');
 59→      return createAnthropic({ apiKey })(modelId);
 60→    }
 61→    case 'GOOGLE': {
 62→      const { createGoogleGenerativeAI } = await import('@ai-sdk/google');
 63→      return createGoogleGenerativeAI({ apiKey })(modelId);
 64→    }
 65→    case 'GROQ': {
 66→      const { createGroq } = await import('@ai-sdk/groq');
 67→      return createGroq({ apiKey })(modelId);
 68→    }
 69→    case 'MISTRAL': {
 70→      const { createMistral } = await import('@ai-sdk/mistral');
 71→      return createMistral({ apiKey })(modelId);
 72→    }
 73→    default:
 74→      throw new Error(`Unsupported provider: ${provider}`);
 75→  }
 76→}
 77→
 78→/**
 79→ * POST /api/[username]/agents/[agentSlug]/conversation/[conversationId]
 80→ * Send a message and stream the AI response via SSE
 81→ */
 82→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic required
 83→export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
 84→  const startTime = Date.now();
 85→
 86→  // Authenticate request (supports both session and API key)
 87→  const authResult = await authenticateRequest();
 88→
 89→  if (!authResult.authenticated) {
 90→    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
 91→  }
 92→
 93→  // Check scope for API key auth
 94→  if (authResult.authenticated && !authResult.isSessionAuth) {
 95→    if (!hasScope(authResult, 'agent:chat')) {
 96→      return NextResponse.json(
 97→        { error: 'API key does not have agent:chat scope' },
 98→        { status: 403 }
 99→      );
100→    }
101→  }
102→
103→  // Check rate limit (after auth so we can track by user if needed)
104→  const rateLimitResponse = checkRateLimit(request, CHAT_RATE_LIMIT);
105→  if (rateLimitResponse) {
106→    return rateLimitResponse;
107→  }
108→
109→  const { username, agentSlug, conversationId } = await context.params;
110→
111→  try {
112→    const body = await request.json();
113→    const parsed = SendMessageSchema.safeParse(body);
114→    if (!parsed.success) {
115→      return NextResponse.json(
116→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
117→        { status: 400 }
118→      );
119→    }
120→
121→    // Fetch agent by username and slug with all tool relations
122→    const { fetchAgentByUsernameAndUidWithTools, buildAgentTools } = await import(
123→      '@/lib/agents/build-tools'
124→    );
125→    const agent = await fetchAgentByUsernameAndUidWithTools(username, agentSlug);
126→
127→    if (!agent) {
128→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
129→    }
130→
131→    // Owner-only enforcement: Only the agent owner can chat with the agent
132→    if (authResult.userId !== agent.userId) {
133→      return NextResponse.json(
134→        {
135→          success: false,
136→          error:
137→            'Fork this agent to use it. Only the agent owner can chat with agents. ' +
138→            'Visit the agent page to fork it to your account.',
139→        },
140→        { status: 403 }
141→      );
142→    }
143→
144→    // Map provider to expected key name format
145→    const providerKeyNames: Record<string, string> = {
146→      OPENAI: 'OPENAI_API_KEY',
147→      ANTHROPIC: 'ANTHROPIC_API_KEY',
148→      GOOGLE: 'GOOGLE_API_KEY',
149→      GROQ: 'GROQ_API_KEY',
150→      MISTRAL: 'MISTRAL_API_KEY',
151→    };
152→    const keyName = providerKeyNames[agent.provider];
153→
154→    if (!keyName) {
155→      return NextResponse.json(
156→        { success: false, error: `Unsupported provider: ${agent.provider}` },
157→        { status: 400 }
158→      );
159→    }
160→
161→    // Get user's API key for this provider
162→    const userApiKey = await prisma.userApiKey.findUnique({
163→      where: {
164→        userId_keyName: {
165→          userId: agent.userId,
166→          keyName,
167→        },
168→      },
169→    });
170→
171→    if (!userApiKey) {
172→      return NextResponse.json(
173→        {
174→          success: false,
175→          error: `No API key configured for ${agent.provider}. Please add your API key in settings.`,
176→        },
177→        { status: 400 }
178→      );
179→    }
180→
181→    // Decrypt the API key
182→    const apiKey = decryptApiKey(userApiKey.encryptedKey, userApiKey.keyIv);
183→
184→    // Get or create conversation
185→    let conversation = await prisma.conversation.findUnique({
186→      where: {
187→        agentId_slug: {
188→          agentId: agent.id,
189→          slug: conversationId,
190→        },
191→      },
192→    });
193→
194→    if (!conversation) {
195→      conversation = await prisma.conversation.create({
196→        data: {
197→          agentId: agent.id,
198→          slug: conversationId,
199→          title: parsed.data.message.slice(0, 100),
200→        },
201→      });
202→
203→      // Log activity for new conversation (fire-and-forget)
204→      if (agent.userId) {
205→        logActivity({
206→          userId: agent.userId,
207→          type: 'AGENT_CONVERSATION_STARTED',
208→          targetName: agent.name,
209→          targetType: 'agent',
210→          agentId: agent.id,
211→        });
212→      }
213→    }
214→
215→    // Fetch recent messages for context
216→    const recentMessages = await prisma.message.findMany({
217→      where: { conversationId: conversation.id },
218→      orderBy: { createdAt: 'desc' },
219→      take: agent.maxMessagesInContext,
220→    });
221→
222→    // Reverse to get chronological order
223→    recentMessages.reverse();
224→
225→    // Save user message
226→    await prisma.message.create({
227→      data: {
228→        conversationId: conversation.id,
229→        role: 'USER',
230→        content: parsed.data.message,
231→      },
232→    });
233→
234→    // Build AI SDK messages from conversation history
235→    const { streamText, stepCountIs } = await import('ai');
236→
237→    const messages: ModelMessage[] = [];
238→
239→    // Add system prompt if defined
240→    if (agent.systemPrompt) {
241→      messages.push({
242→        role: 'system',
243→        content: agent.systemPrompt,
244→      });
245→    }
246→
247→    // Build a set of tool call IDs that have corresponding tool results
248→    // This is needed because AI SDK requires every tool call to have a matching tool result
249→    const toolResultIds = new Set(
250→      recentMessages.filter((m) => m.role === 'TOOL' && m.toolCallId).map((m) => m.toolCallId)
251→    );
252→
253→    // Add conversation history - properly format for AI SDK
254→    for (const msg of recentMessages) {
255→      if (msg.role === 'USER') {
256→        messages.push({ role: 'user', content: msg.content });
257→      } else if (msg.role === 'ASSISTANT') {
258→        // For assistant messages with tool calls, include ToolCallParts in content
259→        if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
260→          // Only include tool calls that have matching tool results
261→          // AI SDK fails if there's a tool call without a corresponding tool result
262→          const validToolCalls = (
263→            msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
264→          ).filter((tc) => toolResultIds.has(tc.toolCallId));
265→
266→          if (validToolCalls.length > 0) {
267→            const toolCallParts = validToolCalls.map((tc) => ({
268→              type: 'tool-call' as const,
269→              toolCallId: tc.toolCallId,
270→              toolName: tc.toolName,
271→              input: tc.args,
272→            }));
273→            // Content includes text (if any) plus tool call parts
274→            const content: Array<
275→              | { type: 'text'; text: string }
276→              | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
277→            > = [];
278→            if (msg.content) {
279→              content.push({ type: 'text', text: msg.content });
280→            }
281→            content.push(...toolCallParts);
282→            messages.push({
283→              role: 'assistant',
284→              content,
285→            });
286→          } else {
287→            // All tool calls are missing results, just include text content
288→            messages.push({
289→              role: 'assistant',
290→              content: msg.content || '',
291→            });
292→          }
293→        } else {
294→          messages.push({
295→            role: 'assistant',
296→            content: msg.content,
297→          });
298→        }
299→      } else if (msg.role === 'TOOL') {
300→        // Tool results use the 'tool' role with content array
301→        messages.push({
302→          role: 'tool',
303→          content: [
304→            {
305→              type: 'tool-result' as const,
306→              toolCallId: msg.toolCallId || '',
307→              toolName: msg.toolName || '',
308→              output: {
309→                type: 'json' as const,
310→                value: msg.toolResult,
311→              },
312→            },
313→          ],
314→        });
315→      }
316→    }
317→
318→    // Add new user message
319→    messages.push({ role: 'user', content: parsed.data.message });
320→
321→    // Set up sandbox session if agent uses sandbox executor
322→    let sessionId: string | undefined;
323→    let _sandboxUrl: string | undefined;
324→    if (agent.executorType === 'sandbox') {
325→      const { parseExecutorConfig, resolveSandboxUrl, createSandboxSession } = await import(
326→        '@/lib/executors'
327→      );
328→      const sandboxConfig = parseExecutorConfig(agent.executorType, agent.executorConfig);
329→      if (sandboxConfig && sandboxConfig.type === 'sandbox') {
330→        const sandboxUrl = resolveSandboxUrl(sandboxConfig);
331→        if (!sandboxUrl) {
332→          return NextResponse.json(
333→            {
334→              success: false,
335→              error:
336→                'Sandbox executor URL not configured. Set AGENT_SANDBOX_URL or provide a custom sandbox URL.',
337→            },
338→            { status: 502 }
339→          );
340→        }
341→        _sandboxUrl = sandboxUrl;
342→        sessionId = `${agent.id}:${conversationId}`;
343→        try {
344→          await createSandboxSession(sandboxUrl, sandboxConfig.apiKey, sessionId);
345→        } catch (error) {
346→          console.error('[Sandbox] Failed to create session:', error);
347→          return NextResponse.json(
348→            {
349→              success: false,
350→              error: `Failed to create sandbox session: ${error instanceof Error ? error.message : 'Unknown error'}`,
351→            },
352→            { status: 502 }
353→          );
354→        }
355→      }
356→    }
357→
358→    // Build tools from agent configuration
359→    const tools = buildAgentTools(agent, undefined, sessionId);
360→
361→    // Get the provider model
362→    const model = await getProviderModel(agent.provider, agent.modelId, apiKey);
363→
364→    // Create SSE stream
365→    const stream = new ReadableStream({
366→      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic
367→      async start(controller) {
368→        const encoder = new TextEncoder();
369→
370→        const sendEvent = (event: string, data: unknown) => {
371→          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
372→          controller.enqueue(encoder.encode(message));
373→        };
374→
375→        try {
376→          const startTime = Date.now();
377→          let fullContent = '';
378→          // Accumulate tool calls with their input args
379→          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
380→            new Map();
381→          // Collect tool results to save AFTER assistant message (for correct chronological order)
382→          const pendingToolResults: Array<{
383→            toolCallId: string;
384→            toolName: string;
385→            output: unknown;
386→          }> = [];
387→          let inputTokens = 0;
388→          let outputTokens = 0;
389→
390→          // Stream the response with agentic loop control
391→          const result = await streamText({
392→            model,
393→            messages,
394→            tools,
395→            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
396→            onChunk: async ({ chunk }) => {
397→              // Stream tool calls as they come in and capture their inputs
398→              if (chunk.type === 'tool-call') {
399→                const input = 'args' in chunk ? chunk.args : chunk.input;
400→
401→                // Log tool call for debugging
402→                console.log('[Agent] Tool call initiated:', {
403→                  toolName: chunk.toolName,
404→                  toolCallId: chunk.toolCallId,
405→                  input: JSON.stringify(input).slice(0, 500),
406→                });
407→
408→                // Store tool call with input for later persistence
409→                toolCallsMap.set(chunk.toolCallId, {
410→                  toolCallId: chunk.toolCallId,
411→                  toolName: chunk.toolName,
412→                  args: input,
413→                });
414→                sendEvent('tool_call', {
415→                  toolCallId: chunk.toolCallId,
416→                  toolName: chunk.toolName,
417→                  input,
418→                });
419→              }
420→            },
421→            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex callback
422→            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
423→              // Capture tool calls from step finish (backup in case onChunk missed any)
424→              if (toolCalls && Array.isArray(toolCalls)) {
425→                for (const tc of toolCalls) {
426→                  if (!toolCallsMap.has(tc.toolCallId)) {
427→                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
428→                    const args =
429→                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
430→                    toolCallsMap.set(tc.toolCallId, {
431→                      toolCallId: tc.toolCallId,
432→                      toolName: tc.toolName,
433→                      args,
434→                    });
435→                  }
436→                }
437→              }
438→
439→              // Send tool results via SSE but don't save yet (save after assistant message for correct order)
440→              if (toolResults && toolResults.length > 0) {
441→                for (const tr of toolResults) {
442→                  // Check if this is an error result (AI SDK wraps errors in the output)
443→                  const isError =
444→                    tr.output && typeof tr.output === 'object' && 'error' in tr.output;
445→
446→                  // Log tool results for debugging
447→                  if (isError) {
448→                    console.error('[Agent] Tool execution failed:', {
449→                      toolName: tr.toolName,
450→                      toolCallId: tr.toolCallId,
451→                      error: tr.output,
452→                    });
453→                  } else {
454→                    console.log('[Agent] Tool execution success:', {
455→                      toolName: tr.toolName,
456→                      toolCallId: tr.toolCallId,
457→                      outputPreview: JSON.stringify(tr.output).slice(0, 200),
458→                    });
459→                  }
460→
461→                  sendEvent('tool_result', {
462→                    toolCallId: tr.toolCallId,
463→                    output: tr.output,
464→                    isError,
465→                  });
466→
467→                  // Collect tool results to save after assistant message
468→                  pendingToolResults.push({
469→                    toolCallId: tr.toolCallId,
470→                    toolName: tr.toolName,
471→                    output: tr.output,
472→                  });
473→
474→                  // Track each tool call execution event
475→                  trackExecution({
476→                    eventType: 'tool_call',
477→                    source: 'agent_chat',
478→                    userId: authResult.userId ?? undefined,
479→                    apiKeyId: authResult.apiKeyId ?? undefined,
480→                    agentId: agent.id,
481→                    toolName: tr.toolName,
482→                    status: isError ? 'error' : 'success',
483→                  });
484→                }
485→              }
486→
487→              // Track token usage
488→              if (usage) {
489→                inputTokens += usage.inputTokens ?? 0;
490→                outputTokens += usage.outputTokens ?? 0;
491→              }
492→            },
493→          });
494→
495→          // Stream text chunks
496→          for await (const chunk of result.textStream) {
497→            fullContent += chunk;
498→            sendEvent('chunk', { type: 'text', text: chunk });
499→          }
500→
501→          // Get final response data
502→          const finalUsage = await result.usage;
503→
504→          // Convert tool calls map to array for storage
505→          const allToolCalls = Array.from(toolCallsMap.values());
506→
507→          // Update token counts from final usage
508→          if (finalUsage) {
509→            inputTokens = finalUsage.inputTokens ?? inputTokens;
510→            outputTokens = finalUsage.outputTokens ?? outputTokens;
511→          }
512→
513→          // Save assistant message FIRST (so it has earlier createdAt than tool results)
514→          const assistantMessage = await prisma.message.create({
515→            data: {
516→              conversationId: conversation.id,
517→              role: 'ASSISTANT',
518→              content: fullContent,
519→              // Cast to Prisma-compatible JSON type
520→              toolCalls:
521→                allToolCalls.length > 0
522→                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
523→                  : Prisma.JsonNull,
524→              inputTokens,
525→              outputTokens,
526→            },
527→          });
528→
529→          // Now save TOOL messages (after assistant, for correct chronological order)
530→          for (const tr of pendingToolResults) {
531→            await prisma.message.create({
532→              data: {
533→                conversationId: conversation.id,
534→                role: 'TOOL',
535→                content: JSON.stringify(tr.output),
536→                toolCallId: tr.toolCallId,
537→                toolName: tr.toolName,
538→                toolResult: tr.output as object,
539→              },
540→            });
541→          }
542→
543→          // Update conversation timestamp
544→          await prisma.conversation.update({
545→            where: { id: conversation.id },
546→            data: { updatedAt: new Date() },
547→          });
548→
549→          const executionTimeMs = Date.now() - startTime;
550→
551→          // Send token usage
552→          sendEvent('tokens', {
553→            inputTokens,
554→            outputTokens,
555→            totalTokens: inputTokens + outputTokens,
556→          });
557→
558→          // Send completion event
559→          sendEvent('complete', {
560→            messageId: assistantMessage.id,
561→            conversationId: conversation.id,
562→            executionTimeMs,
563→          });
564→
565→          // Track agent run execution event
566→          trackExecution({
567→            eventType: 'agent_run',
568→            source: 'agent_chat',
569→            userId: authResult.userId ?? undefined,
570→            apiKeyId: authResult.apiKeyId ?? undefined,
571→            agentId: agent.id,
572→            status: 'success',
573→            durationMs: executionTimeMs,
574→            tokensIn: inputTokens,
575→            tokensOut: outputTokens,
576→          });
577→
578→          // Track usage
579→          if (authResult.userId) {
580→            trackUsage({
581→              apiKeyId: authResult.apiKeyId ?? undefined,
582→              userId: authResult.userId,
583→              endpoint: `/api/${username}/agents/${agentSlug}/conversation/${conversationId}`,
584→              method: 'POST',
585→              statusCode: 200,
586→              latencyMs: executionTimeMs,
587→              resourceType: 'agent',
588→              resourceId: agent.id,
589→              tokensIn: inputTokens,
590→              tokensOut: outputTokens,
591→              model: agent.modelId,
592→            });
593→          }
594→        } catch (error) {
595→          // Log detailed error for debugging
596→          console.error('[Agent] Conversation stream error:', {
597→            error: error instanceof Error ? error.message : String(error),
598→            stack: error instanceof Error ? error.stack : undefined,
599→            agentId: agent.id,
600→            conversationId: conversation.id,
601→          });
602→
603→          // Warn about orphaned sandbox session (TTL cleanup will handle it)
604→          if (sessionId && _sandboxUrl) {
605→            console.warn('[Sandbox] Stream error with active session — will expire via TTL:', {
606→              sessionId,
607→              sandboxUrl: _sandboxUrl,
608→            });
609→          }
610→          sendEvent('error', {
611→            message: error instanceof Error ? error.message : 'Unknown error',
612→          });
613→
614→          // Track agent run error
615→          trackExecution({
616→            eventType: 'agent_run',
617→            source: 'agent_chat',
618→            userId: authResult.userId ?? undefined,
619→            apiKeyId: authResult.apiKeyId ?? undefined,
620→            agentId: agent.id,
621→            status: 'error',
622→            durationMs: Date.now() - startTime,
623→            errorMessage: error instanceof Error ? error.message : 'Unknown error',
624→          });
625→
626→          // Track error
627→          if (authResult.userId) {
628→            trackUsage({
629→              apiKeyId: authResult.apiKeyId ?? undefined,
630→              userId: authResult.userId,
631→              endpoint: `/api/${username}/agents/${agentSlug}/conversation/${conversationId}`,
632→              method: 'POST',
633→              statusCode: 500,
634→              latencyMs: Date.now() - startTime,
635→              resourceType: 'agent',
636→              resourceId: agent.id,
637→              errorCode: 'STREAM_ERROR',
638→              errorMessage: error instanceof Error ? error.message : 'Unknown error',
639→            });
640→          }
641→        } finally {
642→          controller.close();
643→        }
644→      },
645→    });
646→
647→    return new NextResponse(stream, {
648→      headers: {
649→        'Content-Type': 'text/event-stream',
650→        'Cache-Control': 'no-cache',
651→        Connection: 'keep-alive',
652→      },
653→    });
654→  } catch (error) {
655→    console.error('Failed to process message:', error);
656→    return NextResponse.json(
657→      {
658→        success: false,
659→        error: error instanceof Error ? error.message : 'Failed to process message',
660→      },
661→      { status: 500 }
662→    );
663→  }
664→}
