255→
256→      expect(userMessages.length).toBe(3);
257→      expect(assistantMessages.length).toBeGreaterThanOrEqual(3);
258→      // Should have tool messages from shellExec, writeFile, readFile, listFiles
259→      expect(toolMessages.length).toBeGreaterThan(0);
260→    }
261→  });
262→});
