  1→/**
  2→ * Helper functions for working with environment variables in agents and collections
  3→ */
  4→
  5→import type { Agent, AgentCollection, AgentTool, Collection, Package, Tool } from '@tpmjs/db';
  6→import { prisma } from '@tpmjs/db';
  7→import type { TpmjsEnv } from '@tpmjs/types/tpmjs';
  8→
  9→// Reuse the AgentWithRelations type
 10→type AgentWithRelations = Agent & {
 11→  collections: (AgentCollection & {
 12→    collection: Collection & {
 13→      tools: Array<{
 14→        tool: Tool & { package: Package };
 15→      }>;
 16→    };
 17→  })[];
 18→  tools: (AgentTool & {
 19→    tool: Tool & { package: Package };
 20→  })[];
 21→};
 22→
 23→/**
 24→ * Get all required environment variables for an agent's tools
 25→ * Collects env vars from all tools in collections and individual tools
 26→ */
 27→export function getRequiredEnvVarsForAgent(agent: AgentWithRelations): TpmjsEnv[] {
 28→  const envVars = new Map<string, TpmjsEnv>();
 29→
 30→  // Collect from collections
 31→  for (const agentCollection of agent.collections) {
 32→    for (const collectionTool of agentCollection.collection.tools) {
 33→      const packageEnv = collectionTool.tool.package.env as TpmjsEnv[] | null;
 34→      if (packageEnv && Array.isArray(packageEnv)) {
 35→        for (const env of packageEnv) {
 36→          if (!envVars.has(env.name)) {
 37→            envVars.set(env.name, env);
 38→          }
 39→        }
 40→      }
 41→    }
 42→  }
 43→
 44→  // Collect from individual tools
 45→  for (const agentTool of agent.tools) {
 46→    const packageEnv = agentTool.tool.package.env as TpmjsEnv[] | null;
 47→    if (packageEnv && Array.isArray(packageEnv)) {
 48→      for (const env of packageEnv) {
 49→        if (!envVars.has(env.name)) {
 50→          envVars.set(env.name, env);
 51→        }
 52→      }
 53→    }
 54→  }
 55→
 56→  return Array.from(envVars.values());
 57→}
 58→
 59→/**
 60→ * Get required environment variables for a specific tool in a collection
 61→ */
 62→export async function getRequiredEnvVarsForCollectionTool(
 63→  collectionId: string,
 64→  toolName: string
 65→): Promise<TpmjsEnv[]> {
 66→  const collection = await prisma.collection.findUnique({
 67→    where: { id: collectionId },
 68→    include: {
 69→      tools: {
 70→        include: {
 71→          tool: {
 72→            include: { package: true },
 73→          },
 74→        },
 75→      },
 76→    },
 77→  });
 78→
 79→  if (!collection) return [];
 80→
 81→  // Parse tool name to find the matching tool
 82→  // Tool names are in format: sanitized-package-name-toolName
 83→  // e.g., "tpmjs-unsandbox-executeCode"
 84→  for (const ct of collection.tools) {
 85→    const pkgName = ct.tool.package.npmPackageName;
 86→    // Sanitize the package name the same way as in tool-converter
 87→    const sanitizedPkg = pkgName.replace(/[@/]/g, '-').replace(/^-+/, '');
 88→    const expectedToolName = `${sanitizedPkg}-${ct.tool.name}`;
 89→
 90→    if (toolName === expectedToolName || toolName.includes(sanitizedPkg)) {
 91→      const packageEnv = ct.tool.package.env as TpmjsEnv[] | null;
 92→      return packageEnv || [];
 93→    }
 94→  }
 95→
 96→  return [];
 97→}
