 99→/**
100→ * Get all required environment variables for all tools in a collection
101→ */
102→export async function getRequiredEnvVarsForCollection(collectionId: string): Promise<TpmjsEnv[]> {
103→  const collection = await prisma.collection.findUnique({
104→    where: { id: collectionId },
105→    include: {
106→      tools: {
