108→          tool: {
109→            include: { package: true },
110→          },
111→        },
112→      },
113→    },
114→  });
115→
116→  if (!collection) return [];
117→
118→  const envVars = new Map<string, TpmjsEnv>();
119→
120→  for (const ct of collection.tools) {
121→    const packageEnv = ct.tool.package.env as TpmjsEnv[] | null;
122→    if (packageEnv && Array.isArray(packageEnv)) {
123→      for (const env of packageEnv) {
124→        if (!envVars.has(env.name)) {
125→          envVars.set(env.name, env);
126→        }
