147→/**
148→ * Validate that provided env var names are in the allowed list
149→ * Returns invalid names that shouldn't be accepted
150→ */
151→export function getInvalidEnvVarNames(
152→  providedEnvVars: Record<string, string>,
153→  allowedEnvNames: string[]
154→): string[] {
