193→// =============================================================================
194→// Sandbox Session Management
195→// =============================================================================
196→
197→/**
198→ * Resolve sandbox URL from config or environment variable
199→ */
200→export function resolveSandboxUrl(config: SandboxExecutorConfig): string | null {
201→  return config.url || process.env.AGENT_SANDBOX_URL || null;
202→}
203→
204→/**
205→ * Create or resume a sandbox session (idempotent)
206→ * If the session already exists, extends its TTL and returns it.
207→ */
208→export async function createSandboxSession(
209→  url: string,
210→  apiKey: string | undefined,
211→  sessionId: string,
212→  timeoutSeconds?: number
213→): Promise<CreateSessionResponse> {
214→  return withRetry(
215→    async () => {
216→      const headers: Record<string, string> = { 'Content-Type': 'application/json' };
217→      if (apiKey) {
218→        headers.Authorization = `Bearer ${apiKey}`;
219→      }
220→
221→      const controller = new AbortController();
222→      const timeoutId = setTimeout(() => controller.abort(), 15000);
223→
224→      try {
225→        const response = await fetch(`${url}/sessions`, {
226→          method: 'POST',
227→          headers,
228→          body: JSON.stringify({ sessionId, timeoutSeconds }),
229→          signal: controller.signal,
230→        });
231→
232→        clearTimeout(timeoutId);
233→
234→        if (response.status === 429) {
235→          throw new Error('Sandbox at capacity (429). Retrying...');
236→        }
237→
238→        if (!response.ok) {
239→          const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
240→            error?: string;
241→          };
242→          throw new Error(
243→            errorData.error || `Failed to create sandbox session: ${response.status}`
244→          );
245→        }
246→
247→        return (await response.json()) as CreateSessionResponse;
248→      } catch (error) {
249→        clearTimeout(timeoutId);
250→        if (error instanceof Error && error.name === 'AbortError') {
251→          throw new Error('Sandbox session creation timed out');
252→        }
253→        throw error;
254→      }
255→    },
256→    {
257→      shouldRetry: (error) => {
258→        const msg = error instanceof Error ? error.message : String(error);
259→        // Retry on network errors, timeouts, and capacity issues
260→        return (
261→          msg.includes('timed out') ||
262→          msg.includes('429') ||
263→          msg.includes('ECONNREFUSED') ||
264→          msg.includes('fetch failed')
265→        );
266→      },
267→    }
268→  );
269→}
270→
271→/**
272→ * Destroy a sandbox session (fire-and-forget safe)
273→ * Returns gracefully even if the session doesn't exist.
274→ */
275→export async function destroySandboxSession(
276→  url: string,
277→  apiKey: string | undefined,
278→  sessionId: string
279→): Promise<DestroySessionResponse> {
280→  const headers: Record<string, string> = {};
281→  if (apiKey) {
282→    headers.Authorization = `Bearer ${apiKey}`;
283→  }
284→
285→  try {
286→    const controller = new AbortController();
287→    const timeoutId = setTimeout(() => controller.abort(), 10000);
288→
289→    const response = await fetch(`${url}/sessions/${encodeURIComponent(sessionId)}`, {
290→      method: 'DELETE',
291→      headers,
292→      signal: controller.signal,
293→    });
294→
295→    clearTimeout(timeoutId);
296→
297→    if (!response.ok && response.status !== 404) {
298→      return { sessionId, destroyed: false };
299→    }
300→
301→    return (await response
302→      .json()
303→      .catch(() => ({ sessionId, destroyed: true }))) as DestroySessionResponse;
304→  } catch {
305→    // Fire-and-forget: don't throw on cleanup failures
306→    return { sessionId, destroyed: false };
307→  }
308→}
309→
310→/**
311→ * Execute a tool using a sandbox executor (includes sessionId in request)
312→ */
313→async function executeWithSandbox(
314→  url: string,
315→  apiKey: string | undefined,
316→  request: ExecuteToolRequest,
317→  sessionId: string,
318→  timeout: number = DEFAULT_TIMEOUT
319→): Promise<ExecuteToolResponse> {
320→  const startTime = Date.now();
321→
322→  const headers: Record<string, string> = {
323→    'Content-Type': 'application/json',
324→  };
325→
326→  if (apiKey) {
327→    headers.Authorization = `Bearer ${apiKey}`;
328→  }
329→
330→  // Retry on transient failures (network errors, 429, 502, 503)
331→  let lastError: unknown;
332→  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
333→    try {
334→      const controller = new AbortController();
335→      const timeoutId = setTimeout(() => controller.abort(), timeout);
336→
337→      const response = await fetch(`${url}/execute-tool`, {
338→        method: 'POST',
339→        headers,
340→        body: JSON.stringify({ ...request, sessionId }),
341→        signal: controller.signal,
342→      });
343→
344→      clearTimeout(timeoutId);
345→
346→      const executionTimeMs = Date.now() - startTime;
347→
348→      // Retry on 429 (capacity) or 502/503 (transient server issues)
349→      if ((response.status === 429 || response.status === 502 || response.status === 503) && attempt < MAX_RETRIES) {
350→        const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
351→        console.warn(`[Sandbox] Got ${response.status}, retrying in ${delay}ms (attempt ${attempt + 1})`);
352→        await new Promise((resolve) => setTimeout(resolve, delay));
353→        continue;
354→      }
355→
356→      if (!response.ok) {
357→        const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
358→          error?: string;
359→        };
360→        return {
361→          success: false,
362→          error: errorData.error || `Sandbox executor error: ${response.status}`,
363→          executionTimeMs,
364→        };
365→      }
366→
367→      const result = (await response.json()) as ExecuteToolResponse;
368→
369→      return {
370→        success: result.success,
371→        output: result.output,
372→        error: result.error,
373→        executionTimeMs: result.executionTimeMs || executionTimeMs,
374→      };
375→    } catch (error) {
376→      lastError = error;
377→
378→      if (error instanceof Error && error.name === 'AbortError') {
379→        return {
380→          success: false,
381→          error: 'Execution timeout',
382→          executionTimeMs: Date.now() - startTime,
383→        };
384→      }
385→
386→      // Retry on network errors
387→      if (attempt < MAX_RETRIES) {
388→        const msg = error instanceof Error ? error.message : String(error);
389→        if (msg.includes('ECONNREFUSED') || msg.includes('fetch failed') || msg.includes('ECONNRESET')) {
390→          const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
391→          console.warn(`[Sandbox] Network error, retrying in ${delay}ms (attempt ${attempt + 1}):`, msg);
392→          await new Promise((resolve) => setTimeout(resolve, delay));
393→          continue;
394→        }
395→      }
396→
397→      return {
398→        success: false,
399→        error: error instanceof Error ? error.message : String(error),
400→        executionTimeMs: Date.now() - startTime,
401→      };
402→    }
403→  }
404→
405→  return {
406→    success: false,
407→    error: lastError instanceof Error ? lastError.message : String(lastError),
408→    executionTimeMs: Date.now() - startTime,
409→  };
410→}
411→
412→/**
413→ * Execute a tool using the resolved executor configuration
414→ *
415→ * @param config - Resolved executor config (or null for default)
416→ * @param request - Tool execution request
417→ * @param sessionId - Optional session ID for sandbox executors
418→ * @returns Execution result
419→ */
420→export async function executeWithExecutor(
421→  config: ExecutorConfig | null,
422→  request: ExecuteToolRequest,
423→  sessionId?: string
424→): Promise<ExecuteToolResponse> {
425→  const resolvedConfig = config ?? { type: 'default' };
426→
427→  // Use custom URL executor
428→  if (resolvedConfig.type === 'custom_url' && resolvedConfig.url) {
429→    return executeWithCustomUrl(resolvedConfig.url, resolvedConfig.apiKey, request);
430→  }
431→
432→  // Use sandbox executor
433→  if (resolvedConfig.type === 'sandbox' && sessionId) {
434→    const sandboxUrl = resolveSandboxUrl(resolvedConfig);
435→    if (!sandboxUrl) {
436→      return {
437→        success: false,
438→        error:
439→          'Sandbox executor URL not configured. Set AGENT_SANDBOX_URL or provide a custom URL.',
440→        executionTimeMs: 0,
441→      };
442→    }
443→    return executeWithSandbox(sandboxUrl, resolvedConfig.apiKey, request, sessionId);
444→  }
445→
446→  // Default: use existing package-executor (which uses SANDBOX_EXECUTOR_URL)
447→  const result = await executePackage(request.packageName, request.name, request.params, {
448→    env: request.env,
449→    version: request.version,
450→  });
451→
452→  return {
453→    success: result.success,
454→    output: result.output,
455→    error: result.error,
456→    executionTimeMs: result.executionTimeMs,
457→  };
458→}
