 21→  items: DropdownItem[];
 22→}
 23→
 24→function NavDropdown({ label, items }: NavDropdownProps): React.ReactElement {
 25→  const [isOpen, setIsOpen] = useState(false);
 26→  const [focusedIndex, setFocusedIndex] = useState(-1);
 27→  const dropdownRef = useRef<HTMLDivElement>(null);
 28→  const menuRef = useRef<HTMLDivElement>(null);
 29→  const buttonRef = useRef<HTMLButtonElement>(null);
 30→
