}`;

const writeFileResponse = `{
  "success": true,
  "path": "src/main.py",
  "bytesWritten": 58
}`;

const listFilesExample = `// Agent calls listFiles
{
  "path": ".",
  "recursive": true,
  "maxDepth": 2
}`;

const listFilesResponse = `{
  "path": ".",
  "entries": [
    { "name": "repo", "type": "directory", "size": null },
    { "name": "repo/README.md", "type": "file", "size": 1024 },
