460→/**
461→ * Check the health of a custom executor URL
462→ *
463→ * @param url - Executor URL to check
464→ * @param apiKey - Optional API key for authentication
465→ * @returns Health check response or error
466→ */
467→export async function checkExecutorHealth(
468→  url: string,
469→  apiKey?: string
470→): Promise<{ healthy: boolean; response?: ExecutorHealthResponse; error?: string }> {
471→  const headers: Record<string, string> = {};
472→
473→  if (apiKey) {
474→    headers.Authorization = `Bearer ${apiKey}`;
475→  }
476→
477→  try {
478→    const controller = new AbortController();
479→    const timeoutId = setTimeout(() => controller.abort(), 10000); // 10 second timeout for health checks
480→
481→    const response = await fetch(`${url}/health`, {
482→      method: 'GET',
483→      headers,
484→      signal: controller.signal,
485→    });
486→
487→    clearTimeout(timeoutId);
488→
489→    if (!response.ok) {
490→      return {
491→        healthy: false,
492→        error: `Health check failed: ${response.status}`,
493→      };
494→    }
495→
496→    const data = (await response.json()) as ExecutorHealthResponse;
497→
498→    return {
499→      healthy: data.status === 'ok' || data.status === 'degraded',
500→      response: data,
501→    };
502→  } catch (error) {
503→    if (error instanceof Error && error.name === 'AbortError') {
504→      return {
505→        healthy: false,
506→        error: 'Health check timeout',
507→      };
508→    }
509→
510→    return {
511→      healthy: false,
512→      error: error instanceof Error ? error.message : 'Unknown error',
513→    };
514→  }
515→}
