603→/**
604→ * Get executor description for display
605→ */
606→export function getExecutorDescription(config: ExecutorConfig | null): string {
607→  if (!config || config.type === 'default') {
608→    return 'TPMJS Default Executor';
609→  }
610→
611→  if (config.type === 'custom_url') {
612→    try {
613→      const url = new URL(config.url);
614→      return `Custom: ${url.hostname}`;
615→    } catch {
616→      return 'Custom Executor';
617→    }
618→  }
619→
620→  if (config.type === 'sandbox') {
621→    if (config.url) {
622→      try {
623→        const url = new URL(config.url);
624→        return `Sandbox: ${url.hostname}`;
625→      } catch {
626→        return 'Agent Sandbox';
627→      }
628→    }
629→    return 'TPMJS Agent Sandbox';
630→  }
631→
632→  return 'Unknown Executor';
633→}
