  1→/**
  2→ * Sandbox Shell Tools — End-to-end integration test
  3→ *
  4→ * Creates an agent with sandbox executor, attaches a collection owned by
  5→ * thomasalwyndavis@gmail.com, then runs a multi-turn conversation that:
  6→ *   1. Clones https://github.com/thomasdavis/omega
  7→ *   2. Lists the repo contents
  8→ *   3. Creates a new file
  9→ *   4. Commits the change
 10→ *   5. Verifies the commit via git log
 11→ *
 12→ * Requirements:
 13→ *   - INTEGRATION_TESTS=true
 14→ *   - INTEGRATION_TEST_API_KEY / INTEGRATION_TEST_SESSION_TOKEN set
 15→ *   - AGENT_SANDBOX_URL pointing to a running sandbox server
 16→ *   - The sandbox-shell tools registered in the DB
 17→ *   - A collection owned by thomasalwyndavis@gmail.com with sandbox-shell tools
 18→ */
 19→
 20→import { prisma } from '@tpmjs/db';
 21→import { afterAll, beforeAll, describe, expect, it } from 'vitest';
 22→import {
 23→  extractTextFromChunks,
 24→  filterSSEEvents,
 25→  findSSEEvent,
 26→} from '../_helpers/sse-parser';
 27→import {
 28→  cleanupTestContext,
 29→  getTestContext,
 30→  type IntegrationTestContext,
 31→} from '../_helpers/test-context';
 32→
 33→const INTEGRATION_TESTS_ENABLED = process.env.INTEGRATION_TESTS === 'true';
 34→const CONVERSATION_TIMEOUT = 120_000; // 2 minutes per turn (git clone can be slow)
 35→
 36→describe.skipIf(!INTEGRATION_TESTS_ENABLED)('Sandbox Shell E2E — Git Clone & Commit', () => {
 37→  let ctx: IntegrationTestContext;
 38→  let testAgent: { id: string; uid: string; name: string } | null = null;
 39→  let collectionId: string | null = null;
 40→  let conversationSlug: string;
 41→
 42→  beforeAll(async () => {
 43→    ctx = getTestContext();
 44→
 45→    // -----------------------------------------------------------------------
 46→    // 1. Find a collection from thomasalwyndavis@gmail.com that has sandbox-shell tools
 47→    // -----------------------------------------------------------------------
 48→    const userCollection = await prisma.collection.findFirst({
 49→      where: {
 50→        user: { email: 'thomasalwyndavis@gmail.com' },
 51→        tools: {
 52→          some: {
 53→            tool: {
 54→              package: { npmPackageName: '@tpmjs/official-sandbox-shell' },
 55→            },
 56→          },
 57→        },
 58→      },
 59→      select: { id: true, slug: true, name: true },
 60→    });
 61→
 62→    if (!userCollection) {
 63→      // Fallback: find ANY collection with sandbox-shell tools
 64→      const anyCollection = await prisma.collection.findFirst({
 65→        where: {
 66→          tools: {
 67→            some: {
 68→              tool: {
 69→                package: { npmPackageName: '@tpmjs/official-sandbox-shell' },
 70→              },
 71→            },
 72→          },
 73→        },
 74→        select: { id: true, slug: true, name: true },
 75→      });
 76→
 77→      if (!anyCollection) {
 78→        console.warn(
 79→          '⚠️  No collection with @tpmjs/official-sandbox-shell tools found — some tests will be skipped'
 80→        );
 81→        return;
 82→      }
 83→      collectionId = anyCollection.id;
 84→      console.log(`Using fallback collection: ${anyCollection.name} (${anyCollection.slug})`);
 85→    } else {
 86→      collectionId = userCollection.id;
 87→      console.log(`Using collection: ${userCollection.name} (${userCollection.slug})`);
 88→    }
 89→
 90→    // -----------------------------------------------------------------------
 91→    // 2. Create a test agent with sandbox executor
 92→    // -----------------------------------------------------------------------
 93→    testAgent = await ctx.factories.agent.create({
 94→      name: `Sandbox E2E Agent ${Date.now()}`,
 95→      description: 'Integration test agent for sandbox shell tools',
 96→      provider: 'OPENAI',
 97→      modelId: 'gpt-4o-mini',
 98→      systemPrompt: [
 99→        'You are a development assistant with access to a sandbox workspace.',
100→        'You can clone git repos, read/write files, and run shell commands.',
101→        'When asked to do something, use the tools available to you.',
102→        'Be concise in your responses. After completing a task, briefly confirm what you did.',
103→      ].join(' '),
104→      maxToolCallsPerTurn: 10,
105→      collectionIds: [collectionId],
106→    });
107→
108→    // -----------------------------------------------------------------------
109→    // 3. Set the agent executor type to sandbox
110→    // -----------------------------------------------------------------------
111→    await ctx.apiKeyClient.patch(`/api/agents/${testAgent.id}`, {
112→      executorType: 'sandbox',
113→      executorConfig: { type: 'sandbox' },
114→    });
115→
116→    conversationSlug = `test-sandbox-e2e-${Date.now()}`;
117→  });
118→
119→  afterAll(async () => {
120→    await cleanupTestContext();
121→  });
122→
123→  it('should clone a repo, create a file, and commit', async () => {
124→    if (!testAgent || !collectionId) {
125→      console.log('Skipping: No test agent or collection available');
126→      return;
127→    }
128→
129→    // -----------------------------------------------------------------------
130→    // Turn 1: Clone the repo
131→    // -----------------------------------------------------------------------
132→    console.log('Turn 1: Cloning repo...');
133→    const turn1 = await ctx.apiKeyClient.sse(
134→      `/api/${ctx.auth.username}/agents/${testAgent.uid}/conversation/${conversationSlug}`,
135→      {
136→        message:
137→          'Clone the repo https://github.com/thomasdavis/omega with depth 1. Then list the files in it.',
138→      },
139→      { timeout: CONVERSATION_TIMEOUT }
140→    );
141→
142→    expect(turn1.ok).toBe(true);
143→    expect(turn1.status).toBe(200);
144→
145→    const turn1Chunks = filterSSEEvents(turn1.events, 'chunk');
146→    expect(turn1Chunks.length).toBeGreaterThan(0);
147→
148→    const turn1Complete = findSSEEvent(turn1.events, 'complete');
149→    expect(turn1Complete).toBeDefined();
150→
151→    const turn1Text = extractTextFromChunks(turn1.events);
152→    console.log('Turn 1 response:', turn1Text.slice(0, 300));
153→
154→    // Should have used tools (shellExec for git clone, listFiles)
155→    const turn1ToolCalls = filterSSEEvents(turn1.events, 'tool-call');
156→    console.log(
157→      `Turn 1 tool calls: ${turn1ToolCalls.length}`,
158→      turn1ToolCalls.map((e) => (e.data as { toolName?: string }).toolName)
159→    );
160→
161→    // -----------------------------------------------------------------------
162→    // Turn 2: Create a file and commit
163→    // -----------------------------------------------------------------------
164→    console.log('Turn 2: Creating file and committing...');
165→    const turn2 = await ctx.apiKeyClient.sse(
166→      `/api/${ctx.auth.username}/agents/${testAgent.uid}/conversation/${conversationSlug}`,
167→      {
168→        message: [
169→          'In the omega repo directory:',
170→          '1. Create a file called "sandbox-test.txt" with the content "Hello from TPMJS sandbox!"',
171→          '2. Configure git user: git config user.email "test@tpmjs.com" and git config user.name "TPMJS Bot"',
172→          '3. Stage the new file with git add',
173→          '4. Commit with the message "test: add sandbox test file"',
174→          '5. Show me the git log to confirm the commit',
175→        ].join('\n'),
176→      },
177→      { timeout: CONVERSATION_TIMEOUT }
178→    );
179→
180→    expect(turn2.ok).toBe(true);
181→    expect(turn2.status).toBe(200);
182→
183→    const turn2Complete = findSSEEvent(turn2.events, 'complete');
184→    expect(turn2Complete).toBeDefined();
185→
186→    const turn2Text = extractTextFromChunks(turn2.events);
187→    console.log('Turn 2 response:', turn2Text.slice(0, 500));
188→
189→    // The response should mention the commit or the file creation
190→    const turn2ToolCalls = filterSSEEvents(turn2.events, 'tool-call');
191→    console.log(
192→      `Turn 2 tool calls: ${turn2ToolCalls.length}`,
193→      turn2ToolCalls.map((e) => (e.data as { toolName?: string }).toolName)
194→    );
195→
196→    // -----------------------------------------------------------------------
197→    // Turn 3: Verify — read back the file and check git log
198→    // -----------------------------------------------------------------------
199→    console.log('Turn 3: Verifying...');
200→    const turn3 = await ctx.apiKeyClient.sse(
201→      `/api/${ctx.auth.username}/agents/${testAgent.uid}/conversation/${conversationSlug}`,
202→      {
203→        message:
204→          'Read the file omega/sandbox-test.txt and show me the last 3 git log entries in the omega directory.',
205→      },
206→      { timeout: CONVERSATION_TIMEOUT }
207→    );
208→
209→    expect(turn3.ok).toBe(true);
210→    expect(turn3.status).toBe(200);
211→
212→    const turn3Text = extractTextFromChunks(turn3.events);
213→    console.log('Turn 3 response:', turn3Text.slice(0, 500));
214→
215→    // The verification response should contain our file content and commit message
216→    expect(turn3Text).toMatch(/Hello from TPMJS sandbox|sandbox-test/i);
217→  });
218→
219→  it('should retrieve conversation history with tool calls', async () => {
220→    if (!testAgent || !collectionId) {
221→      console.log('Skipping: No test agent or collection available');
222→      return;
223→    }
224→
225→    // Retrieve the conversation we just had
226→    const result = await ctx.apiKeyClient.get<{
227→      success: boolean;
228→      data: {
229→        id: string;
230→        slug: string;
231→        messages: Array<{
232→          role: string;
233→          content: string | null;
234→          toolName: string | null;
235→          toolCallId: string | null;
236→        }>;
237→      };
238→    }>(`/api/${ctx.auth.username}/agents/${testAgent.uid}/conversation/${conversationSlug}`);
239→
240→    expect(result.ok).toBe(true);
241→    if (result.ok) {
242→      expect(result.data.success).toBe(true);
243→      expect(result.data.data.slug).toBe(conversationSlug);
244→
245→      const messages = result.data.data.messages;
246→
247→      // Should have user messages (3 turns), assistant messages, and tool messages
248→      const userMessages = messages.filter((m) => m.role === 'USER');
249→      const assistantMessages = messages.filter((m) => m.role === 'ASSISTANT');
250→      const toolMessages = messages.filter((m) => m.role === 'TOOL');
251→
252→      console.log(
253→        `Conversation: ${userMessages.length} user, ${assistantMessages.length} assistant, ${toolMessages.length} tool messages`
254→      );
255→
256→      expect(userMessages.length).toBe(3);
