  1→/**
  2→ * SSE (Server-Sent Events) parsing utilities for integration tests
  3→ *
  4→ * Used for testing streaming endpoints like agent conversations.
  5→ */
  6→
  7→export interface SSEEvent {
  8→  event: string;
  9→  data: unknown;
 10→  id?: string;
 11→}
 12→
 13→/**
 14→ * Parse SSE response text into array of events
 15→ */
 16→export function parseSSEResponse(text: string): SSEEvent[] {
 17→  const events: SSEEvent[] = [];
 18→  const lines = text.split('\n');
 19→
 20→  let currentEvent = '';
 21→  let currentData = '';
 22→  let currentId: string | undefined;
 23→
 24→  for (const line of lines) {
 25→    if (line.startsWith('event: ')) {
 26→      currentEvent = line.slice(7);
 27→    } else if (line.startsWith('data: ')) {
 28→      currentData = line.slice(6);
 29→      if (currentEvent && currentData) {
 30→        try {
 31→          events.push({
 32→            event: currentEvent,
 33→            data: JSON.parse(currentData),
 34→            id: currentId,
 35→          });
 36→        } catch {
 37→          events.push({
 38→            event: currentEvent,
 39→            data: currentData,
 40→            id: currentId,
 41→          });
 42→        }
 43→        currentEvent = '';
 44→        currentData = '';
 45→        currentId = undefined;
 46→      }
 47→    } else if (line.startsWith('id: ')) {
 48→      currentId = line.slice(4);
 49→    }
 50→  }
 51→
 52→  return events;
 53→}
 54→
 55→/**
 56→ * Collect SSE events from a streaming response
 57→ */
 58→export async function collectSSEEvents(
 59→  response: Response,
 60→  options: {
 61→    timeout?: number;
 62→    maxEvents?: number;
 63→  } = {}
 64→): Promise<SSEEvent[]> {
 65→  const { timeout = 30000, maxEvents = 1000 } = options;
 66→
 67→  if (!response.body) {
 68→    throw new Error('Response has no body');
 69→  }
 70→
 71→  const events: SSEEvent[] = [];
 72→  const reader = response.body.getReader();
 73→  const decoder = new TextDecoder();
 74→  let buffer = '';
 75→
 76→  const timeoutPromise = new Promise<never>((_, reject) => {
 77→    setTimeout(() => reject(new Error(`SSE collection timed out after ${timeout}ms`)), timeout);
 78→  });
 79→
 80→  try {
 81→    await Promise.race([
 82→      (async () => {
 83→        while (events.length < maxEvents) {
 84→          const { done, value } = await reader.read();
 85→
 86→          if (done) break;
 87→
 88→          buffer += decoder.decode(value, { stream: true });
 89→
 90→          // Process complete events in buffer
 91→          const lines = buffer.split('\n');
 92→          buffer = lines.pop() || ''; // Keep incomplete line in buffer
 93→
 94→          let currentEvent = '';
 95→          let currentData = '';
 96→          let currentId: string | undefined;
 97→
 98→          for (const line of lines) {
 99→            if (line.startsWith('event: ')) {
100→              currentEvent = line.slice(7);
101→            } else if (line.startsWith('data: ')) {
102→              currentData = line.slice(6);
103→              if (currentEvent && currentData) {
104→                try {
105→                  events.push({
106→                    event: currentEvent,
107→                    data: JSON.parse(currentData),
108→                    id: currentId,
109→                  });
110→                } catch {
111→                  events.push({
112→                    event: currentEvent,
113→                    data: currentData,
114→                    id: currentId,
115→                  });
116→                }
117→                currentEvent = '';
118→                currentData = '';
119→                currentId = undefined;
120→              }
121→            } else if (line.startsWith('id: ')) {
122→              currentId = line.slice(4);
123→            }
124→          }
125→        }
126→      })(),
127→      timeoutPromise,
128→    ]);
129→  } finally {
130→    reader.releaseLock();
131→  }
132→
133→  return events;
134→}
135→
136→/**
137→ * Find an SSE event by event type
138→ */
139→export function findSSEEvent(events: SSEEvent[], eventType: string): SSEEvent | undefined {
140→  return events.find((e) => e.event === eventType);
141→}
142→
