 42→// Module cache
 43→const CACHE_TTL_MS = 2 * 60 * 1000;
 44→const MAX_CACHE_SIZE = 200;
 45→
 46→interface CacheEntry {
 47→  // biome-ignore lint/suspicious/noExplicitAny: Tool types are dynamic
 48→  module: any;
 49→  expiresAt: number;
 50→  isFactory: boolean;
 51→}
 52→
 53→const moduleCache = new Map<string, CacheEntry>();
 54→
 55→// ─── Session Management ─────────────────────────────────────────────────────
 56→
 57→interface Session {
 58→  sessionId: string;
 59→  workDir: string;
 60→  createdAt: Date;
 61→  expiresAt: Date;
 62→  toolCallCount: number;
 63→}
 64→
 65→const sessions = new Map<string, Session>();
 66→
 67→function getSessionWorkDir(sessionId: string): string {
 68→  // Sanitize sessionId to be filesystem-safe
 69→  const safe = sessionId.replace(/[^a-zA-Z0-9_:-]/g, '_');
 70→  return `${SESSIONS_BASE_DIR}/${safe}/workspace`;
 71→}
 72→
 73→async function createSession(
 74→  sessionId: string,
 75→  timeoutSeconds?: number
 76→): Promise<Session & { resumed: boolean }> {
 77→  const ttl = timeoutSeconds ?? DEFAULT_SESSION_TTL_SECONDS;
 78→
 79→  // Idempotent: if session exists, extend TTL and return it
 80→  const existing = sessions.get(sessionId);
 81→  if (existing) {
 82→    existing.expiresAt = new Date(Date.now() + ttl * 1000);
 83→    console.log(`🔄 Session resumed: ${sessionId} (TTL extended to ${ttl}s)`);
 84→    return { ...existing, resumed: true };
 85→  }
 86→
 87→  // Check concurrent session limit
 88→  if (sessions.size >= MAX_CONCURRENT_SESSIONS) {
 89→    throw new Error(
 90→      `Maximum concurrent sessions reached (${MAX_CONCURRENT_SESSIONS}). Try again later.`
 91→    );
 92→  }
 93→
 94→  const workDir = getSessionWorkDir(sessionId);
 95→
 96→  // Create workspace directory
 97→  await Deno.mkdir(workDir, { recursive: true });
 98→
 99→  const session: Session = {
100→    sessionId,
101→    workDir,
102→    createdAt: new Date(),
103→    expiresAt: new Date(Date.now() + ttl * 1000),
104→    toolCallCount: 0,
105→  };
106→
107→  sessions.set(sessionId, session);
108→  metrics.totalSessionsCreated++;
109→  console.log(`✅ Session created: ${sessionId} (TTL: ${ttl}s, workDir: ${workDir})`);
110→
111→  return { ...session, resumed: false };
112→}
113→
114→async function destroySession(sessionId: string): Promise<boolean> {
115→  const session = sessions.get(sessionId);
116→  if (!session) {
117→    return false;
118→  }
119→
120→  sessions.delete(sessionId);
121→
122→  // Clean up workspace directory
123→  try {
124→    await Deno.remove(session.workDir, { recursive: true });
125→    // Also remove parent directory (the sessionId dir)
126→    const parentDir = session.workDir.replace(/\/workspace$/, '');
127→    await Deno.remove(parentDir, { recursive: true }).catch(() => {});
128→  } catch {
129→    // Directory may already be cleaned up
130→  }
131→
132→  metrics.totalSessionsDestroyed++;
133→  console.log(`🗑️  Session destroyed: ${sessionId}`);
134→  return true;
135→}
136→
137→function getSession(sessionId: string): Session | null {
138→  const session = sessions.get(sessionId);
139→  if (!session) return null;
140→
141→  // Check if expired
142→  if (new Date() > session.expiresAt) {
143→    // Mark for cleanup but don't block
144→    destroySession(sessionId).catch(() => {});
145→    return null;
146→  }
147→
148→  return session;
149→}
150→
151→// ─── Session Cleanup ────────────────────────────────────────────────────────
152→
153→async function cleanupExpiredSessions(): Promise<void> {
154→  const now = new Date();
155→  let cleaned = 0;
156→
157→  for (const [sessionId, session] of sessions.entries()) {
158→    if (now > session.expiresAt) {
159→      await destroySession(sessionId).catch(() => {});
160→      cleaned++;
161→    }
162→  }
163→
164→  if (cleaned > 0) {
165→    console.log(`🗑️  Cleaned ${cleaned} expired sessions (${sessions.size} remaining)`);
166→  }
167→}
168→
169→// Run session cleanup every 60 seconds
170→setInterval(cleanupExpiredSessions, 60 * 1000);
171→
172→// ─── Module Cache ───────────────────────────────────────────────────────────
173→
174→function getCachedModule(cacheKey: string): CacheEntry | null {
175→  const entry = moduleCache.get(cacheKey);
176→  if (!entry) return null;
177→  if (Date.now() > entry.expiresAt) {
178→    moduleCache.delete(cacheKey);
179→    return null;
180→  }
181→  return entry;
182→}
183→
184→// biome-ignore lint/suspicious/noExplicitAny: Tool types are dynamic
185→function setCachedModule(cacheKey: string, module: any, isFactory: boolean): void {
186→  if (moduleCache.size >= MAX_CACHE_SIZE) {
187→    const entriesToEvict = Math.max(1, Math.floor(MAX_CACHE_SIZE * 0.2));
188→    const keys = Array.from(moduleCache.keys());
189→    for (let i = 0; i < entriesToEvict && i < keys.length; i++) {
190→      moduleCache.delete(keys[i]);
191→    }
192→  }
193→  moduleCache.set(cacheKey, {
194→    module,
195→    expiresAt: Date.now() + CACHE_TTL_MS,
196→    isFactory,
197→  });
198→}
199→
200→function cleanupExpiredCache(): void {
201→  const now = Date.now();
202→  for (const [key, entry] of moduleCache.entries()) {
203→    if (now > entry.expiresAt) {
204→      moduleCache.delete(key);
205→    }
206→  }
207→}
208→
209→setInterval(cleanupExpiredCache, 60 * 1000);
210→
211→// ─── Auth Middleware ─────────────────────────────────────────────────────────
212→
213→function checkAuth(req: Request): boolean {
214→  if (!EXECUTOR_API_KEY) return true;
215→  const authHeader = req.headers.get('Authorization');
216→  if (!authHeader) return false;
217→  const token = authHeader.replace('Bearer ', '');
218→  return token === EXECUTOR_API_KEY;
219→}
220→
221→// ─── CORS Headers ───────────────────────────────────────────────────────────
222→
223→function corsHeaders(): Record<string, string> {
224→  return {
225→    'Access-Control-Allow-Origin': '*',
226→    'Access-Control-Allow-Methods': 'GET, POST, DELETE, OPTIONS',
227→    'Access-Control-Allow-Headers': 'Content-Type, Authorization',
228→  };
229→}
230→
231→// ─── Tool Loading & Execution ───────────────────────────────────────────────
232→
233→// biome-ignore lint/suspicious/noExplicitAny: Dynamic tool loading
234→async function loadTool(
235→  packageName: string,
236→  name: string,
237→  version: string,
238→  importUrl?: string
239→): Promise<any> {
240→  const cacheKey = `${packageName}::${name}`;
241→
242→  const cached = getCachedModule(cacheKey);
243→  if (cached) {
244→    return cached.module;
245→  }
246→
247→  const url = importUrl || `https://esm.sh/${packageName}@${version}`;
248→  console.log(`📦 Importing: ${url}`);
249→
250→  const module = await import(url);
251→  let rawExport = module[name];
252→
253→  if (!rawExport) {
254→    throw new Error(
255→      `Export "${name}" not found in module. Available: ${Object.keys(module).join(', ')}`
256→    );
257→  }
258→
259→  // Check if it's a factory function
260→  if (typeof rawExport === 'function' && !rawExport.description && !rawExport.execute) {
261→    console.log(`🏭 Detected factory function for ${cacheKey}, attempting to call...`);
262→
263→    let factoryResult = null;
264→
265→    // Strategy 1: no arguments
266→    try {
267→      factoryResult = rawExport();
268→      if (factoryResult?.description && factoryResult?.execute) {
269→        rawExport = factoryResult;
270→      } else {
271→        factoryResult = null;
272→      }
273→    } catch {
274→      factoryResult = null;
275→    }
276→
277→    // Strategy 2: empty config object
278→    if (!factoryResult) {
279→      try {
280→        factoryResult = rawExport({});
281→        if (factoryResult?.description && factoryResult?.execute) {
282→          rawExport = factoryResult;
283→        }
284→      } catch {
285→        // Not a factory
286→      }
287→    }
288→  }
289→
290→  const isFactory = rawExport !== module[name];
291→  setCachedModule(cacheKey, rawExport, isFactory);
292→
293→  return rawExport;
294→}
295→
296→// ─── Route Handlers ─────────────────────────────────────────────────────────
297→
298→async function handleCreateSession(req: Request): Promise<Response> {
299→  try {
300→    const body = await req.json();
301→    const { sessionId, timeoutSeconds } = body;
302→
303→    if (!sessionId || typeof sessionId !== 'string') {
304→      return Response.json(
305→        { error: 'sessionId is required' },
306→        { status: 400, headers: corsHeaders() }
307→      );
308→    }
309→
310→    const session = await createSession(sessionId, timeoutSeconds);
311→
312→    return Response.json(
313→      {
314→        sessionId: session.sessionId,
315→        workDir: session.workDir,
316→        createdAt: session.createdAt.toISOString(),
317→        expiresAt: session.expiresAt.toISOString(),
318→        resumed: session.resumed,
319→      },
320→      { status: 200, headers: corsHeaders() }
321→    );
322→  } catch (error) {
323→    const message = error instanceof Error ? error.message : 'Failed to create session';
324→    console.error('❌ Create session error:', message);
325→    return Response.json({ error: message }, { status: 500, headers: corsHeaders() });
326→  }
327→}
328→
329→function handleGetSession(sessionId: string): Response {
330→  const session = getSession(sessionId);
331→
332→  if (!session) {
333→    return Response.json(
334→      { error: 'Session not found or expired' },
335→      { status: 404, headers: corsHeaders() }
336→    );
337→  }
338→
339→  return Response.json(
340→    {
341→      sessionId: session.sessionId,
342→      workDir: session.workDir,
343→      createdAt: session.createdAt.toISOString(),
344→      expiresAt: session.expiresAt.toISOString(),
345→      toolCallCount: session.toolCallCount,
346→    },
347→    { status: 200, headers: corsHeaders() }
348→  );
349→}
350→
351→async function handleDestroySession(sessionId: string): Promise<Response> {
352→  const destroyed = await destroySession(sessionId);
353→
354→  return Response.json({ sessionId, destroyed }, { status: 200, headers: corsHeaders() });
355→}
356→
357→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Tool execution with session support
358→async function handleExecuteTool(req: Request): Promise<Response> {
359→  const startTime = Date.now();
360→
361→  try {
362→    const body = await req.json();
363→    const { packageName, name, version, importUrl, params, env, sessionId } = body;
364→
365→    if (!packageName || !name) {
366→      return Response.json(
367→        { success: false, error: 'Missing required fields: packageName, name' },
368→        { status: 400, headers: corsHeaders() }
369→      );
370→    }
371→
372→    // Load the tool
373→    const tool = await loadTool(packageName, name, version || 'latest', importUrl);
374→
375→    if (!tool || typeof tool.execute !== 'function') {
376→      return Response.json(
377→        { success: false, error: `"${name}" is not a valid tool (missing execute function)` },
378→        { status: 400, headers: corsHeaders() }
379→      );
380→    }
381→
382→    // Resolve session workspace for cwd if sessionId provided
383→    let cwd: string | undefined;
384→    if (sessionId) {
385→      const session = getSession(sessionId);
386→      if (session) {
387→        cwd = session.workDir;
388→        session.toolCallCount++;
389→        // Extend session TTL on each tool call
390→        session.expiresAt = new Date(Date.now() + DEFAULT_SESSION_TTL_SECONDS * 1000);
391→      }
392→    }
393→
394→    // Enforce disk quota before execution
395→    if (cwd) {
396→      const usageKB = await getDirectorySizeKB(cwd);
397→      const quotaKB = SESSION_DISK_QUOTA_MB * 1024;
398→      if (usageKB > quotaKB) {
399→        return Response.json(
400→          {
401→            success: false,
402→            error: `Session disk quota exceeded: ${Math.round(usageKB / 1024)}MB / ${SESSION_DISK_QUOTA_MB}MB`,
403→            executionTimeMs: Date.now() - startTime,
404→          },
405→          { status: 413, headers: corsHeaders() }
406→        );
407→      }
408→    }
409→
410→    // Set environment variables if provided
411→    if (env && typeof env === 'object') {
412→      for (const [key, value] of Object.entries(env)) {
413→        if (typeof value === 'string') {
414→          Deno.env.set(key, value);
415→        }
416→      }
417→    }
418→
419→    // Execute the tool, injecting cwd into params if session is active
420→    const executeParams = cwd ? { ...params, _sandboxWorkDir: cwd } : params;
421→    const output = await tool.execute(executeParams);
422→
423→    // Clean up injected env vars
424→    if (env && typeof env === 'object') {
425→      for (const key of Object.keys(env)) {
426→        try {
427→          Deno.env.delete(key);
428→        } catch {
429→          // Some vars may be read-only
430→        }
431→      }
432→    }
433→
434→    const executionTimeMs = Date.now() - startTime;
435→    metrics.totalExecutions++;
436→    metrics.successfulExecutions++;
437→
438→    return Response.json(
439→      { success: true, output, executionTimeMs },
440→      { status: 200, headers: corsHeaders() }
441→    );
442→  } catch (error) {
443→    const executionTimeMs = Date.now() - startTime;
444→    const message = error instanceof Error ? error.message : String(error);
445→    console.error('❌ Execute tool error:', message);
446→    metrics.totalExecutions++;
447→    metrics.failedExecutions++;
448→
449→    return Response.json(
450→      { success: false, error: message, executionTimeMs },
451→      { status: 200, headers: corsHeaders() }
452→    );
453→  }
454→}
455→
456→// ─── Disk Quota Helper ──────────────────────────────────────────────────────
457→
458→async function getDirectorySizeKB(dir: string): Promise<number> {
459→  try {
460→    const cmd = new Deno.Command('du', { args: ['-sk', dir], stdout: 'piped', stderr: 'piped' });
461→    const { stdout } = await cmd.output();
462→    const output = new TextDecoder().decode(stdout);
463→    const sizeKB = parseInt(output.split('\t')[0], 10);
464→    return isNaN(sizeKB) ? 0 : sizeKB;
465→  } catch {
466→    return 0;
467→  }
468→}
469→
470→function handleMetrics(): Response {
471→  const memInfo = Deno.memoryUsage();
472→  return Response.json(
473→    {
474→      uptime: Date.now() - metrics.startTime,
475→      sessions: {
476→        active: sessions.size,
477→        max: MAX_CONCURRENT_SESSIONS,
478→        totalCreated: metrics.totalSessionsCreated,
479→        totalDestroyed: metrics.totalSessionsDestroyed,
480→      },
481→      executions: {
482→        total: metrics.totalExecutions,
483→        successful: metrics.successfulExecutions,
484→        failed: metrics.failedExecutions,
485→      },
486→      memory: {
487→        rss: memInfo.rss,
488→        heapUsed: memInfo.heapUsed,
489→        heapTotal: memInfo.heapTotal,
490→      },
491→      cache: {
492→        modules: moduleCache.size,
493→        maxSize: MAX_CACHE_SIZE,
494→      },
495→    },
496→    { status: 200, headers: corsHeaders() }
497→  );
498→}
499→
500→function handleHealth(): Response {
501→  return Response.json(
502→    {
503→      status: 'ok',
504→      version: '1.0.0',
505→      info: {
506→        runtime: 'deno',
507→        denoVersion: Deno.version.deno,
508→        activeSessions: sessions.size,
509→        maxSessions: MAX_CONCURRENT_SESSIONS,
510→        cachedModules: moduleCache.size,
511→        capabilities: {
512→          sessions: true,
513→          executeToolWithSession: true,
514→        },
515→      },
516→    },
517→    { status: 200, headers: corsHeaders() }
518→  );
519→}
520→
521→// ─── Request Router ─────────────────────────────────────────────────────────
522→
523→async function handler(req: Request): Promise<Response> {
524→  const url = new URL(req.url);
525→  const { pathname } = url;
526→  const method = req.method;
527→
528→  // CORS preflight
529→  if (method === 'OPTIONS') {
530→    return new Response(null, { status: 204, headers: corsHeaders() });
531→  }
532→
533→  // Health check (no auth required)
534→  if (pathname === '/health' && method === 'GET') {
535→    return handleHealth();
536→  }
537→
538→  // Metrics (no auth required, for monitoring)
539→  if (pathname === '/metrics' && method === 'GET') {
540→    return handleMetrics();
541→  }
542→
543→  // Auth check for all other routes
544→  if (!checkAuth(req)) {
545→    return Response.json({ error: 'Unauthorized' }, { status: 401, headers: corsHeaders() });
546→  }
547→
548→  // Session endpoints
549→  if (pathname === '/sessions' && method === 'POST') {
550→    return handleCreateSession(req);
551→  }
552→
553→  const sessionMatch = pathname.match(/^\/sessions\/(.+)$/);
554→  if (sessionMatch) {
555→    const sessionId = decodeURIComponent(sessionMatch[1]);
556→    if (method === 'GET') {
557→      return handleGetSession(sessionId);
558→    }
559→    if (method === 'DELETE') {
560→      return handleDestroySession(sessionId);
561→    }
562→  }
563→
564→  // Tool execution
565→  if (pathname === '/execute-tool' && method === 'POST') {
566→    return handleExecuteTool(req);
567→  }
568→
569→  return Response.json({ error: 'Not Found' }, { status: 404, headers: corsHeaders() });
570→}
571→
572→// ─── Server Startup ─────────────────────────────────────────────────────────
573→
574→// Ensure sessions directory exists
575→try {
576→  await Deno.mkdir(SESSIONS_BASE_DIR, { recursive: true });
577→} catch {
578→  // May already exist
579→}
580→
581→// Clean up orphaned session directories from previous server runs
582→async function cleanupOrphanedSessions(): Promise<void> {
583→  try {
584→    let cleaned = 0;
585→    for await (const entry of Deno.readDir(SESSIONS_BASE_DIR)) {
586→      if (entry.isDirectory && !sessions.has(entry.name)) {
587→        const dir = `${SESSIONS_BASE_DIR}/${entry.name}`;
588→        await Deno.remove(dir, { recursive: true }).catch(() => {});
589→        cleaned++;
590→      }
591→    }
592→    if (cleaned > 0) {
593→      console.log(`🗑️  Cleaned ${cleaned} orphaned session directories from previous run`);
594→    }
595→  } catch {
596→    // Directory may be empty or inaccessible
597→  }
598→}
599→await cleanupOrphanedSessions();
600→
601→console.log(`🚀 TPMJS Agent Sandbox Server starting on port ${PORT}`);
602→console.log(`📁 Sessions base dir: ${SESSIONS_BASE_DIR}`);
603→console.log(`🔒 Auth: ${EXECUTOR_API_KEY ? 'enabled' : 'disabled'}`);
604→console.log(`📊 Max sessions: ${MAX_CONCURRENT_SESSIONS}, TTL: ${DEFAULT_SESSION_TTL_SECONDS}s`);
605→
606→Deno.serve({ port: PORT }, handler);
607→
608→// ─── Graceful Shutdown ──────────────────────────────────────────────────────
609→
610→async function shutdown(signal: string) {
611→  console.log(`\n${signal} received. Cleaning up ${sessions.size} sessions...`);
612→
613→  // Destroy all sessions
614→  for (const sessionId of sessions.keys()) {
615→    await destroySession(sessionId).catch(() => {});
616→  }
617→
618→  console.log('✅ Cleanup complete. Exiting.');
619→  Deno.exit(0);
620→}
621→
622→Deno.addSignalListener('SIGTERM', () => shutdown('SIGTERM'));
623→Deno.addSignalListener('SIGINT', () => shutdown('SIGINT'));
