  1→/**
  2→ * Integration test context manager
  3→ *
  4→ * Provides a unified context object for integration tests with:
  5→ * - Authenticated fetch functions (session, API key, cron)
  6→ * - API client
  7→ * - Data factories
  8→ * - Cleanup tracker
  9→ */
 10→
 11→import { type ApiClient, createApiClient } from './api-client';
 12→import {
 13→  createApiKeyFetch,
 14→  createCronFetch,
 15→  createSessionFetch,
 16→  getTestAuthContext,
 17→  type TestAuthContext,
 18→} from './auth';
 19→import { TestDataTracker } from './cleanup';
 20→import { type AgentFactory, createAgentFactory } from './factories/agent.factory';
 21→import { type CollectionFactory, createCollectionFactory } from './factories/collection.factory';
 22→
 23→export interface IntegrationTestContext {
 24→  /** Base URL for API requests */
 25→  baseUrl: string;
 26→
 27→  /** Test user authentication context */
 28→  auth: TestAuthContext;
 29→
 30→  /** API client with session authentication */
 31→  api: ApiClient;
 32→
 33→  /** API client with API key authentication */
 34→  apiKeyClient: ApiClient;
 35→
 36→  /** API client with cron authentication */
 37→  cronClient: ApiClient;
 38→
 39→  /** Unauthenticated API client */
 40→  publicClient: ApiClient;
 41→
 42→  /** Fetch with session cookie */
 43→  sessionFetch: typeof fetch;
 44→
 45→  /** Fetch with API key header */
 46→  apiKeyFetch: typeof fetch;
 47→
 48→  /** Fetch with cron secret header */
 49→  cronFetch: typeof fetch;
 50→
 51→  /** Data factories */
 52→  factories: {
 53→    agent: AgentFactory;
 54→    collection: CollectionFactory;
 55→  };
 56→
 57→  /** Test data tracker for cleanup */
 58→  tracker: TestDataTracker;
 59→}
 60→
 61→let cachedContext: IntegrationTestContext | null = null;
 62→
 63→/**
 64→ * Get or create the integration test context
 65→ *
 66→ * This is a singleton that's reused across all tests in a run.
 67→ * The tracker and factories are reset for each test file.
 68→ */
 69→export function getTestContext(): IntegrationTestContext {
 70→  if (cachedContext) {
 71→    return cachedContext;
 72→  }
 73→
 74→  const baseUrl = process.env.TEST_BASE_URL || 'https://tpmjs.com';
 75→  const auth = getTestAuthContext();
 76→
 77→  // Create authenticated fetch functions
 78→  const sessionFetch = createSessionFetch(auth.sessionToken);
 79→  const apiKeyFetch = createApiKeyFetch(auth.apiKey);
 80→  const cronFetch = createCronFetch();
 81→
 82→  // Create API clients
 83→  const api = createApiClient(baseUrl, sessionFetch);
 84→  const apiKeyClient = createApiClient(baseUrl, apiKeyFetch);
 85→  const cronClient = createApiClient(baseUrl, cronFetch);
 86→  const publicClient = createApiClient(baseUrl);
 87→
 88→  // Create tracker
 89→  const tracker = new TestDataTracker();
 90→
 91→  // Create factories (use API key client since session auth requires better-auth sessions)
 92→  const factories = {
 93→    agent: createAgentFactory(apiKeyClient, tracker),
 94→    collection: createCollectionFactory(apiKeyClient, tracker),
 95→  };
 96→
 97→  cachedContext = {
 98→    baseUrl,
 99→    auth,
100→    api,
101→    apiKeyClient,
102→    cronClient,
103→    publicClient,
104→    sessionFetch,
105→    apiKeyFetch,
106→    cronFetch,
107→    factories,
108→    tracker,
109→  };
110→
111→  return cachedContext;
112→}
113→
114→/**
115→ * Reset the test context tracker
116→ *
117→ * Call this in afterAll() to clean up test data.
118→ */
119→export async function cleanupTestContext(): Promise<void> {
120→  if (cachedContext) {
121→    await cachedContext.tracker.cleanup();
122→  }
123→}
124→
125→/**
126→ * Create a fresh test context with its own tracker
127→ *
128→ * Use this when you need isolated test data that won't
129→ * interfere with other tests.
130→ */
131→export function createFreshTestContext(): IntegrationTestContext {
132→  const baseUrl = process.env.TEST_BASE_URL || 'https://tpmjs.com';
133→  const auth = getTestAuthContext();
134→
135→  const sessionFetch = createSessionFetch(auth.sessionToken);
136→  const apiKeyFetch = createApiKeyFetch(auth.apiKey);
137→  const cronFetch = createCronFetch();
138→
139→  const api = createApiClient(baseUrl, sessionFetch);
140→  const apiKeyClient = createApiClient(baseUrl, apiKeyFetch);
141→  const cronClient = createApiClient(baseUrl, cronFetch);
142→  const publicClient = createApiClient(baseUrl);
143→
144→  const tracker = new TestDataTracker();
145→
146→  // Use API key client for factories since session auth requires better-auth sessions
147→  const factories = {
148→    agent: createAgentFactory(apiKeyClient, tracker),
149→    collection: createCollectionFactory(apiKeyClient, tracker),
150→  };
151→
152→  return {
153→    baseUrl,
154→    auth,
155→    api,
156→    apiKeyClient,
157→    cronClient,
158→    publicClient,
159→    sessionFetch,
160→    apiKeyFetch,
161→    cronFetch,
162→    factories,
163→    tracker,
164→  };
165→}
