  1→/**
  2→ * Agent factory for integration tests
  3→ *
  4→ * Creates test agents with auto-generated test prefixes
  5→ * and tracks them for cleanup.
  6→ */
  7→
  8→import type { ApiClient } from '../api-client';
  9→import type { TestDataTracker } from '../cleanup';
 10→
 11→export interface CreateAgentOptions {
 12→  uid?: string;
 13→  name?: string;
 14→  description?: string;
 15→  provider?: 'OPENAI' | 'ANTHROPIC' | 'GOOGLE' | 'GROQ' | 'MISTRAL';
 16→  modelId?: string;
 17→  systemPrompt?: string;
 18→  temperature?: number;
 19→  maxToolCallsPerTurn?: number;
 20→  maxMessagesInContext?: number;
 21→  isPublic?: boolean;
 22→  toolIds?: string[];
 23→  collectionIds?: string[];
 24→}
 25→
 26→export interface AgentFactoryResult {
 27→  id: string;
 28→  uid: string;
 29→  name: string;
 30→  description: string | null;
 31→  provider: string;
 32→  modelId: string;
 33→  isPublic: boolean;
 34→}
 35→
 36→/**
 37→ * Create an agent factory bound to a specific API client and tracker
 38→ */
 39→export function createAgentFactory(api: ApiClient, tracker: TestDataTracker) {
 40→  let counter = 0;
 41→
 42→  return {
 43→    /**
 44→     * Create a new test agent
 45→     */
 46→    async create(options: CreateAgentOptions = {}): Promise<AgentFactoryResult> {
 47→      counter++;
 48→      const timestamp = Date.now();
 49→
 50→      const uid = options.uid || `test-agent-${timestamp}-${counter}`;
 51→      const name = options.name || `Test Agent ${timestamp}-${counter}`;
 52→
 53→      const result = await api.post<{ success: boolean; data: AgentFactoryResult }>('/api/agents', {
 54→        uid,
 55→        name,
 56→        description: options.description ?? 'Integration test agent',
 57→        provider: options.provider ?? 'OPENAI',
 58→        modelId: options.modelId ?? 'gpt-4o-mini',
 59→        systemPrompt: options.systemPrompt ?? 'You are a helpful test agent.',
 60→        temperature: options.temperature ?? 0.7,
 61→        maxToolCallsPerTurn: options.maxToolCallsPerTurn ?? 5,
 62→        maxMessagesInContext: options.maxMessagesInContext ?? 10,
 63→        isPublic: options.isPublic ?? true,
 64→      });
 65→
 66→      if (!result.ok) {
 67→        const errorResult = result as { error: string; status: number };
 68→        throw new Error(
 69→          `Failed to create agent: ${errorResult.error} (status: ${errorResult.status})`
 70→        );
 71→      }
 72→
 73→      const agent = result.data.data;
 74→      tracker.trackAgent(agent.id);
 75→
 76→      // Add tools if specified
 77→      if (options.toolIds && options.toolIds.length > 0) {
 78→        for (const toolId of options.toolIds) {
 79→          await api.post(`/api/agents/${agent.id}/tools`, { toolId });
 80→        }
 81→      }
 82→
 83→      // Add collections if specified
 84→      if (options.collectionIds && options.collectionIds.length > 0) {
 85→        for (const collectionId of options.collectionIds) {
 86→          await api.post(`/api/agents/${agent.id}/collections`, { collectionId });
 87→        }
 88→      }
 89→
 90→      return agent;
 91→    },
 92→
 93→    /**
 94→     * Create multiple test agents
 95→     */
 96→    async createMany(
 97→      count: number,
 98→      options: CreateAgentOptions = {}
 99→    ): Promise<AgentFactoryResult[]> {
100→      const agents: AgentFactoryResult[] = [];
101→      for (let i = 0; i < count; i++) {
102→        const agent = await this.create({
103→          ...options,
104→          uid: options.uid ? `${options.uid}-${i}` : undefined,
105→          name: options.name ? `${options.name} ${i}` : undefined,
106→        });
107→        agents.push(agent);
108→      }
109→      return agents;
110→    },
111→
112→    /**
113→     * Get an agent by ID
114→     */
115→    async get(id: string): Promise<AgentFactoryResult | null> {
116→      const result = await api.get<{ success: boolean; data: AgentFactoryResult }>(
117→        `/api/agents/${id}`
118→      );
119→      if (!result.ok) {
120→        return null;
121→      }
122→      return result.data.data;
123→    },
124→
125→    /**
126→     * Update an agent
127→     */
128→    async update(id: string, updates: Partial<CreateAgentOptions>): Promise<AgentFactoryResult> {
129→      const result = await api.patch<{ success: boolean; data: AgentFactoryResult }>(
130→        `/api/agents/${id}`,
131→        updates
132→      );
133→      if (!result.ok) {
134→        throw new Error(`Failed to update agent: ${(result as { error: string }).error}`);
135→      }
136→      return result.data.data;
137→    },
138→
139→    /**
140→     * Delete an agent
141→     */
142→    async delete(id: string): Promise<void> {
143→      const result = await api.delete(`/api/agents/${id}`);
144→      if (!result.ok) {
145→        throw new Error(`Failed to delete agent: ${(result as { error: string }).error}`);
146→      }
147→    },
148→  };
149→}
150→
151→export type AgentFactory = ReturnType<typeof createAgentFactory>;
