  1→/**
  2→ * Sandbox Shell Tools for TPMJS Agent Sandbox
  3→ *
  4→ * Execute shell commands, read/write files, and list directories
  5→ * within the stateful sandbox workspace. All paths are resolved
  6→ * relative to `_sandboxWorkDir` (injected by the sandbox server).
  7→ *
  8→ * Runs inside Deno — uses Deno.Command, Deno.readTextFile, etc.
  9→ */
 10→
 11→import { jsonSchema, tool } from 'ai';
 12→
 13→// ---------------------------------------------------------------------------
 14→// Constants
 15→// ---------------------------------------------------------------------------
 16→
 17→const MAX_STDOUT = 100 * 1024; // 100 KB
 18→const MAX_READ_SIZE = 500 * 1024; // 500 KB
 19→const DEFAULT_TIMEOUT_MS = 30_000;
 20→const MAX_TIMEOUT_MS = 300_000;
 21→const MAX_LIST_ENTRIES = 1_000;
 22→const DEFAULT_MAX_DEPTH = 3;
 23→
 24→// ---------------------------------------------------------------------------
 25→// Result types
 26→// ---------------------------------------------------------------------------
 27→
 28→export interface ShellExecResult {
 29→  stdout: string;
 30→  stderr: string;
 31→  exitCode: number;
 32→  durationMs: number;
 33→  truncated: boolean;
 34→}
 35→
 36→export interface ReadFileResult {
 37→  content: string;
 38→  path: string;
 39→  size: number;
 40→  truncated: boolean;
 41→}
 42→
 43→export interface WriteFileResult {
 44→  success: boolean;
 45→  path: string;
 46→  bytesWritten: number;
 47→}
 48→
 49→export interface FileEntry {
 50→  name: string;
 51→  type: 'file' | 'directory' | 'symlink';
 52→  size: number | null;
 53→}
 54→
 55→export interface ListFilesResult {
 56→  path: string;
 57→  entries: FileEntry[];
 58→  truncated: boolean;
 59→}
 60→
 61→// ---------------------------------------------------------------------------
 62→// Helpers
 63→// ---------------------------------------------------------------------------
 64→
 65→function resolveSandboxPath(workDir: string, relativePath: string): string {
 66→  // Normalize: remove leading slash (paths are relative to workDir)
 67→  const cleaned = relativePath.replace(/^\/+/, '');
 68→
 69→  // Simple join — Deno runs on Linux so forward slashes only
 70→  const resolved = `${workDir}/${cleaned}`.replace(/\/+/g, '/');
 71→
 72→  // Security: ensure the resolved path stays inside workDir
 73→  // Normalize away any .. segments by splitting and resolving
 74→  const parts = resolved.split('/');
 75→  const normalized: string[] = [];
 76→  for (const part of parts) {
 77→    if (part === '..') {
 78→      normalized.pop();
 79→    } else if (part !== '.' && part !== '') {
 80→      normalized.push(part);
 81→    }
 82→  }
 83→  const final = '/' + normalized.join('/');
 84→
 85→  const normalizedWorkDir = '/' + workDir.replace(/^\/+/, '').replace(/\/+$/, '');
 86→  if (!final.startsWith(normalizedWorkDir)) {
 87→    throw new Error(`Path escapes sandbox workspace: ${relativePath}`);
 88→  }
 89→
 90→  return final;
 91→}
 92→
 93→function truncate(text: string, maxBytes: number): { text: string; truncated: boolean } {
 94→  const encoder = new TextEncoder();
 95→  const bytes = encoder.encode(text);
 96→  if (bytes.length <= maxBytes) {
 97→    return { text, truncated: false };
 98→  }
 99→  // Truncate at byte boundary, decode back (may lose partial char)
100→  const decoder = new TextDecoder('utf-8', { fatal: false });
101→  return {
102→    text: decoder.decode(bytes.slice(0, maxBytes)) + '\n... [truncated]',
103→    truncated: true,
104→  };
105→}
106→
107→async function collectStream(
108→  stream: ReadableStream<Uint8Array>,
109→  maxBytes: number = MAX_STDOUT * 2,
110→): Promise<Uint8Array> {
111→  const reader = stream.getReader();
112→  const chunks: Uint8Array[] = [];
113→  let totalLength = 0;
114→  try {
115→    while (true) {
116→      const { done, value } = await reader.read();
117→      if (done) break;
118→      chunks.push(value);
119→      totalLength += value.length;
120→      // Prevent OOM: stop reading if we exceed the limit
121→      if (totalLength > maxBytes) {
122→        reader.cancel().catch(() => {});
123→        break;
124→      }
125→    }
126→  } finally {
127→    reader.releaseLock();
128→  }
129→  const cappedLength = Math.min(totalLength, maxBytes);
130→  const result = new Uint8Array(cappedLength);
131→  let offset = 0;
132→  for (const chunk of chunks) {
133→    const copyLen = Math.min(chunk.length, cappedLength - offset);
134→    if (copyLen <= 0) break;
135→    result.set(chunk.subarray(0, copyLen), offset);
136→    offset += copyLen;
137→  }
138→  return result.subarray(0, offset);
139→}
140→
141→// ---------------------------------------------------------------------------
142→// shellExec
143→// ---------------------------------------------------------------------------
144→
145→type ShellExecInput = {
146→  command: string;
147→  timeout?: number;
148→  _sandboxWorkDir?: string;
149→};
150→
151→export const shellExec = tool({
152→  description:
153→    'Execute a shell command in the sandbox workspace. Supports git, npm, and any CLI tools available in the container.',
154→  inputSchema: jsonSchema<ShellExecInput>({
155→    type: 'object',
156→    properties: {
157→      command: {
158→        type: 'string',
159→        description: 'Shell command to execute (passed to sh -c)',
160→      },
161→      timeout: {
162→        type: 'number',
163→        description: 'Timeout in milliseconds (default: 30000, max: 300000)',
164→      },
165→      _sandboxWorkDir: {
166→        type: 'string',
167→        description: 'Injected by sandbox server — workspace directory',
168→      },
169→    },
170→    required: ['command'],
171→    additionalProperties: false,
172→  }),
173→  async execute({ command, timeout, _sandboxWorkDir }) {
174→    if (!_sandboxWorkDir) {
175→      throw new Error('shellExec requires a sandbox session (_sandboxWorkDir not set)');
176→    }
177→
178→    const timeoutMs = Math.min(Math.max(timeout ?? DEFAULT_TIMEOUT_MS, 1000), MAX_TIMEOUT_MS);
179→    const startTime = Date.now();
180→
181→    const cmd = new Deno.Command('sh', {
182→      args: ['-c', command],
183→      cwd: _sandboxWorkDir,
184→      stdout: 'piped',
185→      stderr: 'piped',
186→    });
187→
188→    const child = cmd.spawn();
189→
190→    // Timeout handling — kill the process tree if it exceeds the limit
191→    let timedOut = false;
192→    const timer = setTimeout(() => {
193→      timedOut = true;
194→      try {
195→        // Try SIGTERM first for graceful shutdown
196→        child.kill('SIGTERM');
197→        // Force kill after 2 seconds if still running
198→        setTimeout(() => {
199→          try {
200→            child.kill('SIGKILL');
201→          } catch {
202→            // Already exited
203→          }
204→        }, 2000);
205→      } catch {
206→        // Process may have already exited
207→      }
208→    }, timeoutMs);
209→
210→    try {
211→      // Collect stdout and stderr concurrently
212→      const [stdoutBytes, stderrBytes, status] = await Promise.all([
213→        collectStream(child.stdout),
214→        collectStream(child.stderr),
215→        child.status,
216→      ]);
217→
218→      clearTimeout(timer);
219→      const durationMs = Date.now() - startTime;
220→      const decoder = new TextDecoder('utf-8', { fatal: false });
221→
222→      const stdoutRaw = decoder.decode(stdoutBytes);
223→      const stderrRaw = decoder.decode(stderrBytes);
224→
225→      const stdout = truncate(stdoutRaw, MAX_STDOUT);
226→      const stderr = truncate(stderrRaw, MAX_STDOUT);
227→
228→      const result: ShellExecResult = {
229→        stdout: stdout.text,
230→        stderr: timedOut ? `[TIMEOUT after ${timeoutMs}ms] ${stderr.text}` : stderr.text,
231→        exitCode: timedOut ? 137 : status.code,
232→        durationMs,
233→        truncated: stdout.truncated || stderr.truncated,
234→      };
235→
236→      return result;
237→    } catch (error) {
238→      clearTimeout(timer);
239→      throw new Error(
240→        `Shell execution failed: ${error instanceof Error ? error.message : String(error)}`,
241→      );
242→    }
243→  },
244→});
