322→export const writeFile = tool({
323→  description: 'Write or create a file in the sandbox workspace.',
324→  inputSchema: jsonSchema<WriteFileInput>({
325→    type: 'object',
326→    properties: {
327→      path: {
328→        type: 'string',
329→        description: 'File path relative to workspace root',
330→      },
331→      content: {
332→        type: 'string',
333→        description: 'Content to write to the file',
334→      },
335→      createDirs: {
336→        type: 'boolean',
337→        description: 'Create parent directories if they do not exist (default: true)',
338→      },
339→      _sandboxWorkDir: {
340→        type: 'string',
341→        description: 'Injected by sandbox server — workspace directory',
342→      },
343→    },
344→    required: ['path', 'content'],
345→    additionalProperties: false,
346→  }),
347→  async execute({ path: filePath, content, createDirs = true, _sandboxWorkDir }) {
348→    if (!_sandboxWorkDir) {
349→      throw new Error('writeFile requires a sandbox session (_sandboxWorkDir not set)');
350→    }
351→
352→    const resolved = resolveSandboxPath(_sandboxWorkDir, filePath);
353→
354→    // Create parent directories if requested
355→    if (createDirs) {
356→      const parentDir = resolved.substring(0, resolved.lastIndexOf('/'));
357→      if (parentDir) {
358→        await Deno.mkdir(parentDir, { recursive: true });
359→      }
360→    }
361→
362→    await Deno.writeTextFile(resolved, content);
363→
364→    const encoder = new TextEncoder();
365→    const bytesWritten = encoder.encode(content).length;
366→
367→    const result: WriteFileResult = {
368→      success: true,
369→      path: filePath,
370→      bytesWritten,
371→    };
372→
373→    return result;
374→  },
