377→// ---------------------------------------------------------------------------
378→// listFiles
379→// ---------------------------------------------------------------------------
380→
381→type ListFilesInput = {
382→  path?: string;
383→  recursive?: boolean;
384→  maxDepth?: number;
385→  _sandboxWorkDir?: string;
386→};
387→
388→export const listFiles = tool({
389→  description: 'List files and directories in the sandbox workspace.',
390→  inputSchema: jsonSchema<ListFilesInput>({
391→    type: 'object',
392→    properties: {
393→      path: {
394→        type: 'string',
395→        description: 'Directory path relative to workspace root (default: root)',
396→      },
397→      recursive: {
398→        type: 'boolean',
399→        description: 'List recursively (default: false)',
400→      },
401→      maxDepth: {
402→        type: 'number',
403→        description: 'Maximum depth for recursive listing (default: 3)',
404→      },
405→      _sandboxWorkDir: {
406→        type: 'string',
407→        description: 'Injected by sandbox server — workspace directory',
408→      },
409→    },
410→    additionalProperties: false,
411→  }),
412→  async execute({ path: dirPath = '.', recursive = false, maxDepth, _sandboxWorkDir }) {
413→    if (!_sandboxWorkDir) {
414→      throw new Error('listFiles requires a sandbox session (_sandboxWorkDir not set)');
415→    }
416→
417→    const effectiveMaxDepth = maxDepth ?? DEFAULT_MAX_DEPTH;
418→    const resolved = resolveSandboxPath(_sandboxWorkDir, dirPath);
419→    const entries: FileEntry[] = [];
420→    let truncated = false;
421→
422→    const normalizedWorkDir = '/' + _sandboxWorkDir.replace(/^\/+/, '').replace(/\/+$/, '');
423→
424→    async function walk(dir: string, depth: number, prefix: string): Promise<void> {
425→      if (entries.length >= MAX_LIST_ENTRIES) {
426→        truncated = true;
427→        return;
428→      }
429→
430→      for await (const entry of Deno.readDir(dir)) {
431→        if (entries.length >= MAX_LIST_ENTRIES) {
432→          truncated = true;
433→          return;
434→        }
435→
436→        const entryPath = `${dir}/${entry.name}`;
437→        const displayName = prefix ? `${prefix}/${entry.name}` : entry.name;
438→
439→        // Skip symlinks that escape the workspace
440→        if (entry.isSymlink) {
441→          try {
442→            const realPath = await Deno.realPath(entryPath);
443→            if (!realPath.startsWith(normalizedWorkDir)) {
444→              continue; // silently skip symlinks that point outside
445→            }
446→          } catch {
447→            continue; // skip broken symlinks
448→          }
449→        }
450→
451→        let size: number | null = null;
452→        if (entry.isFile) {
453→          try {
454→            const info = await Deno.stat(entryPath);
455→            size = info.size;
456→          } catch {
457→            // Permission or race condition — skip size
458→          }
459→        }
460→
461→        entries.push({
462→          name: displayName,
463→          type: entry.isDirectory ? 'directory' : entry.isSymlink ? 'symlink' : 'file',
464→          size,
465→        });
466→
467→        if (recursive && entry.isDirectory && depth < effectiveMaxDepth) {
468→          await walk(entryPath, depth + 1, displayName);
469→        }
470→      }
471→    }
472→
473→    await walk(resolved, 0, '');
474→
475→    const result: ListFilesResult = {
476→      path: dirPath,
477→      entries,
478→      truncated,
479→    };
480→
481→    return result;
482→  },
483→});
484→
