420→export async function executeWithExecutor(
421→  config: ExecutorConfig | null,
422→  request: ExecuteToolRequest,
423→  sessionId?: string
424→): Promise<ExecuteToolResponse> {
425→  const resolvedConfig = config ?? { type: 'default' };
