```typescript
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import {
  getSandboxTestContext,
  isSandboxAvailable,
  type SandboxTestContext,
} from './_helpers/sandbox-context';

const SANDBOX_AVAILABLE = isSandboxAvailable();
const TOOL_PACKAGE = '@tpmjs/official-sandbox-shell';
const TOOL_VERSION = '0.1.0';

describe.skipIf(!SANDBOX_AVAILABLE)('Sandbox Server — Tool Execution', () => {
  let ctx: SandboxTestContext;
  let sessionId: string;

  beforeAll(async () => {
    ctx = getSandboxTestContext();
    sessionId = ctx.uniqueSessionId('tools');
    ctx.trackSession(sessionId);
    await ctx.client.createSession(sessionId);
  });

  afterAll(async () => {
    await ctx.cleanup();
  });

  describe('shellExec', () => {
    it('should execute echo command', async () => {
      const result = await ctx.client.executeTool({
        packageName: TOOL_PACKAGE,
        name: 'shellExec',
        version: TOOL_VERSION,
        params: { command: 'echo "hello sandbox"' },
        sessionId,
      });

      expect(result.success).toBe(true);
      const output = result.output as { stdout: string; exitCode: number };
      expect(output.exitCode).toBe(0);
      expect(output.stdout).toContain('hello sandbox');
    });

    it('should return non-zero exit code for failing command', async () => {
      const result = await ctx.client.executeTool({
        packageName: TOOL_PACKAGE,
        name: 'shellExec',
        version: TOOL_VERSION,
        params: { command: 'exit 42' },
        sessionId,
      });

      expect(result.success).toBe(true); // execute-tool returns success even for non-zero exit
      const output = result.output as { exitCode: number };
      expect(output.exitCode).toBe(42);
    });

    it('should handle timeout', async () => {
      const result = await ctx.client.executeTool({
        packageName: TOOL_PACKAGE,
        name: 'shellExec',
        version: TOOL_VERSION,
        params: { command: 'sleep 60', timeout: 2000 },
        sessionId,
      });

      expect(result.success).toBe(true);
      const output = result.output as { exitCode: number; stderr: string };
      expect(output.exitCode).toBe(137); // Killed by timeout
      expect(output.stderr).toContain('TIMEOUT');
    }, 15_000); // Allow generous vitest timeout
  });

  describe('writeFile + readFile round-trip', () => {
    it('should write then read a file', async () => {
      const content = 'Hello from integration test!\nLine 2.';

      const writeResult = await ctx.client.executeTool({
        packageName: TOOL_PACKAGE,
        name: 'writeFile',
        version: TOOL_VERSION,
        params: { path: 'test-roundtrip.txt', content },
        sessionId,
      });

      expect(writeResult.success).toBe(true);
      const writeOutput = writeResult.output as { success: boolean; bytesWritten: number };
      expect(writeOutput.success).toBe(true);
      expect(writeOutput.bytesWritten).toBeGreaterThan(0);

      const readResult = await ctx.client.executeTool({
        packageName: TOOL_PACKAGE,
        name: 'readFile',
        version: TOOL_VERSION,
        params: { path: 'test-roundtrip.txt' },
        sessionId,
      });

      expect(readResult.success).toBe(true);
      const readOutput = readResult.output as { content: string; path: string };
      expect(readOutput.content).toBe(content);
      expect(readOutput.path).toBe('test-roundtrip.txt');
    });

    it('should create parent directories with createDirs', async () => {
      const result = await ctx.client.executeTool({
        packageName: TOOL_PACKAGE,
        name: 'writeFile',
        version: TOOL_VERSION,
        params: { path: 'deep/nested/dir/file.txt', content: 'deep file', createDirs: true },
        sessionId,
      });

      expect(result.success).toBe(true);

      const readResult = await ctx.client.executeTool({
        packageName: TOOL_PACKAGE,
        name: 'readFile',
        version: TOOL_VERSION,
        params: { path: 'deep/nested/dir/file.txt' },
        sessionId,
      });

      expect(readResult.success).toBe(true);
      expect((readResult.output as { content: string }).content).toBe('deep file');
    });
  });

  describe('listFiles', () => {
    it('should list files in workspace root', async () => {
      const result = await ctx.client.executeTool({
        packageName: TOOL_PACKAGE,
        name: 'listFiles',
        version: TOOL_VERSION,
        params: {},
        sessionId,
      });

      expect(result.success).toBe(true);
      const output = result.output as { entries: Array<{ name: string; type: string }> };
      expect(output.entries.length).toBeGreaterThan(0);
      // Should include files created in prior tests
      const names = output.entries.map((e) => e.name);
      expect(names).toContain('test-roundtrip.txt');
    });

    it('should list recursively', async () => {
      const result = await ctx.client.executeTool({
        packageName: TOOL_PACKAGE,
        name: 'listFiles',
        version: TOOL_VERSION,
        params: { recursive: true },
        sessionId,
      });

      expect(result.success).toBe(true);
      const output = result.output as { entries: Array<{ name: string }> };
      const names = output.entries.map((e) => e.name);
      expect(names.some((n) => n.includes('deep/nested'))).toBe(true);
    });
  });
});
