  });

  it('should reject tool execution when disk quota is exceeded', async () => {
    // This test requires the sandbox to have a low disk quota configured
    // CI sets SESSION_DISK_QUOTA_MB=5 for this test
    const quotaMB = Number(process.env.SANDBOX_TEST_DISK_QUOTA_MB || '5');
    const sessionId = ctx.uniqueSessionId('quota');
    ctx.trackSession(sessionId);

    await ctx.client.createSession(sessionId);

    // Fill the workspace beyond the quota
    // Create a file slightly larger than the quota
    const fillCommand = `dd if=/dev/zero of=bigfile.bin bs=1M count=${quotaMB + 2} 2>&1`;
    await ctx.client.executeTool({
      packageName: TOOL_PACKAGE,
      name: 'shellExec',
      version: TOOL_VERSION,
      params: { command: fillCommand },
      sessionId,
    });

    // Next tool call should fail with quota error
    const result = await ctx.client.executeTool({
      packageName: TOOL_PACKAGE,
      name: 'shellExec',
      version: TOOL_VERSION,
      params: { command: 'echo should-fail' },
      sessionId,
    });

    expect(result.success).toBe(false);
    expect(result.error).toContain('disk quota exceeded');
