### 2. New Files to Create

#### 2.1 Sandbox API Client Helper

**File**: `apps/web/src/test/integration/sandbox/_helpers/sandbox-client.ts`

This is a lightweight HTTP client purpose-built for talking directly to the sandbox server. It intentionally does NOT reuse the web app's `api-client.ts` because that one injects TPMJS authentication headers (session cookies, API keys) which are irrelevant for the sandbox server's own Bearer token auth.

```typescript
/**
 * Sandbox server HTTP client for direct API tests
 * 
 * Separate from the web app's api-client because the sandbox
 * has its own auth scheme (EXECUTOR_API_KEY Bearer token) and 
 * different response shapes.
 */

export interface SandboxClientConfig {
  baseUrl: string;
  apiKey?: string;
}

export interface SandboxHealthResponse {
  status: string;
  version: string;
  info: {
    runtime: string;
    denoVersion: string;
    activeSessions: number;
    maxSessions: number;
    cachedModules: number;
    capabilities: {
      sessions: boolean;
      executeToolWithSession: boolean;
    };
  };
}

export interface SandboxMetricsResponse {
  uptime: number;
  sessions: {
    active: number;
    max: number;
    totalCreated: number;
    totalDestroyed: number;
  };
  executions: {
    total: number;
    successful: number;
    failed: number;
  };
  memory: {
    rss: number;
    heapUsed: number;
    heapTotal: number;
  };
  cache: {
    modules: number;
    maxSize: number;
  };
}

export interface SandboxSessionResponse {
  sessionId: string;
  workDir: string;
  createdAt: string;
  expiresAt: string;
  resumed?: boolean;
  toolCallCount?: number;
}

export interface SandboxExecuteResponse {
  success: boolean;
  output?: unknown;
  error?: string;
  executionTimeMs: number;
}

export function createSandboxClient(config: SandboxClientConfig) {
  const { baseUrl, apiKey } = config;
  const normalizedUrl = baseUrl.replace(/\/$/, '');

  function headers(includeAuth = true): Record<string, string> {
    const h: Record<string, string> = { 'Content-Type': 'application/json' };
    if (includeAuth && apiKey) {
      h['Authorization'] = `Bearer ${apiKey}`;
    }
    return h;
  }

  return {
    // --- Health (no auth) ---
    async health(): Promise<SandboxHealthResponse> {
      const res = await fetch(`${normalizedUrl}/health`);
      if (!res.ok) throw new Error(`Health check failed: ${res.status}`);
      return res.json();
    },

    // --- Metrics (no auth) ---
    async metrics(): Promise<SandboxMetricsResponse> {
      const res = await fetch(`${normalizedUrl}/metrics`);
      if (!res.ok) throw new Error(`Metrics failed: ${res.status}`);
      return res.json();
    },

    // --- Sessions ---
    async createSession(sessionId: string, timeoutSeconds?: number): Promise<SandboxSessionResponse> {
      const res = await fetch(`${normalizedUrl}/sessions`, {
        method: 'POST',
        headers: headers(),
        body: JSON.stringify({ sessionId, timeoutSeconds }),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(`Create session failed (${res.status}): ${(err as any).error || 'unknown'}`);
      }
      return res.json();
    },

    async getSession(sessionId: string): Promise<SandboxSessionResponse> {
      const res = await fetch(`${normalizedUrl}/sessions/${encodeURIComponent(sessionId)}`, {
        headers: headers(),
      });
      if (!res.ok) {
        throw new Error(`Get session failed: ${res.status}`);
      }
      return res.json();
    },

    async destroySession(sessionId: string): Promise<{ sessionId: string; destroyed: boolean }> {
      const res = await fetch(`${normalizedUrl}/sessions/${encodeURIComponent(sessionId)}`, {
        method: 'DELETE',
        headers: headers(),
      });
      return res.json();
    },

    // --- Tool execution ---
    async executeTool(params: {
      packageName: string;
      name: string;
      version?: string;
      params?: Record<string, unknown>;
      sessionId?: string;
      env?: Record<string, string>;
    }): Promise<SandboxExecuteResponse> {
      const res = await fetch(`${normalizedUrl}/execute-tool`, {
        method: 'POST',
        headers: headers(),
        body: JSON.stringify(params),
      });
      return res.json();
    },

    // --- Raw request (for auth testing) ---
    async rawRequest(method: string, path: string, opts?: {
      body?: unknown;
      includeAuth?: boolean;
    }): Promise<Response> {
      return fetch(`${normalizedUrl}${path}`, {
        method,
        headers: headers(opts?.includeAuth ?? true),
        body: opts?.body ? JSON.stringify(opts.body) : undefined,
      });
    },
  };
}

export type SandboxClient = ReturnType<typeof createSandboxClient>;
```

**Design rationale**: A distinct client avoids coupling the sandbox tests to the web app's authentication machinery. The sandbox server's own auth is a simple Bearer token, not a session cookie. The response types match the server's actual API shapes directly.

