#### 2.2 Sandbox Test Fixture/Context

**File**: `apps/web/src/test/integration/sandbox/_helpers/sandbox-context.ts`

```typescript
/**
 * Sandbox test context — provides a configured SandboxClient
 * and helpers for session cleanup.
 * 
 * Reads SANDBOX_TEST_URL and SANDBOX_TEST_API_KEY from env.
 * When these are absent, sandbox tests skip gracefully.
 */

import { createSandboxClient, type SandboxClient } from './sandbox-client';

export interface SandboxTestContext {
  client: SandboxClient;
  baseUrl: string;
  apiKey: string | undefined;
  /** Generate a unique session ID for a test */
  uniqueSessionId: (prefix?: string) => string;
  /** Track session IDs for cleanup */
  trackSession: (sessionId: string) => void;
  /** Cleanup all tracked sessions */
  cleanup: () => Promise<void>;
}

let counter = 0;

export function isSandboxAvailable(): boolean {
  return !!process.env.SANDBOX_TEST_URL;
}

export function getSandboxTestContext(): SandboxTestContext {
  const baseUrl = process.env.SANDBOX_TEST_URL || 'http://localhost:3002';
  const apiKey = process.env.SANDBOX_TEST_API_KEY;

  const client = createSandboxClient({ baseUrl, apiKey });
  const trackedSessions: string[] = [];

  return {
    client,
    baseUrl,
    apiKey,
    uniqueSessionId(prefix = 'test') {
      counter++;
      return `${prefix}-${Date.now()}-${counter}`;
    },
    trackSession(sessionId: string) {
      trackedSessions.push(sessionId);
    },
    async cleanup() {
      for (const sessionId of trackedSessions) {
        try {
          await client.destroySession(sessionId);
        } catch {
          // Best effort cleanup
        }
      }
      trackedSessions.length = 0;
    },
  };
}
```

**Design rationale**: The `isSandboxAvailable()` function gates all Layer 1 tests. In CI, the `SANDBOX_TEST_URL` env var is set by the workflow. Locally, developers can run the sandbox container and set the var themselves. The context tracks sessions for automatic cleanup in `afterAll`, mirroring the `TestDataTracker` pattern.

