##### 2.3.2 Session Lifecycle Tests

**File**: `apps/web/src/test/integration/sandbox/sandbox-sessions.integration.test.ts`

```typescript
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import {
  getSandboxTestContext,
  isSandboxAvailable,
  type SandboxTestContext,
} from './_helpers/sandbox-context';

const SANDBOX_AVAILABLE = isSandboxAvailable();

describe.skipIf(!SANDBOX_AVAILABLE)('Sandbox Server — Session Lifecycle', () => {
  let ctx: SandboxTestContext;

  beforeAll(() => {
    ctx = getSandboxTestContext();
  });

  afterAll(async () => {
    await ctx.cleanup();
  });

  it('should create a new session', async () => {
    const sessionId = ctx.uniqueSessionId('lifecycle');
    ctx.trackSession(sessionId);

    const session = await ctx.client.createSession(sessionId);
    expect(session.sessionId).toBe(sessionId);
    expect(session.workDir).toContain('workspace');
    expect(session.createdAt).toBeDefined();
    expect(session.expiresAt).toBeDefined();
    expect(session.resumed).toBe(false);
  });

  it('should retrieve an existing session', async () => {
    const sessionId = ctx.uniqueSessionId('get');
    ctx.trackSession(sessionId);

    await ctx.client.createSession(sessionId);
    const session = await ctx.client.getSession(sessionId);
    expect(session.sessionId).toBe(sessionId);
    expect(session.toolCallCount).toBe(0);
  });

  it('should resume an existing session (idempotent creation)', async () => {
    const sessionId = ctx.uniqueSessionId('resume');
    ctx.trackSession(sessionId);

    const first = await ctx.client.createSession(sessionId);
    expect(first.resumed).toBe(false);

    const second = await ctx.client.createSession(sessionId);
    expect(second.resumed).toBe(true);
    expect(second.sessionId).toBe(sessionId);
  });

  it('should destroy a session', async () => {
    const sessionId = ctx.uniqueSessionId('destroy');
    await ctx.client.createSession(sessionId);

    const result = await ctx.client.destroySession(sessionId);
    expect(result.destroyed).toBe(true);

    // GET should now return 404
    try {
      await ctx.client.getSession(sessionId);
      expect.fail('Expected getSession to throw after destroy');
    } catch (error) {
      expect((error as Error).message).toContain('404');
    }
  });

  it('should return 404 for non-existent session', async () => {
    try {
      await ctx.client.getSession('nonexistent-session-id');
      expect.fail('Expected getSession to throw for non-existent session');
    } catch (error) {
      expect((error as Error).message).toContain('404');
    }
  });

  it('should reject creation without sessionId', async () => {
    const res = await ctx.client.rawRequest('POST', '/sessions', {
      body: {},
    });
    expect(res.status).toBe(400);
  });

  it('should support custom TTL', async () => {
    const sessionId = ctx.uniqueSessionId('ttl');
    ctx.trackSession(sessionId);

    const session = await ctx.client.createSession(sessionId, 120); // 2 minutes
    const expiresAt = new Date(session.expiresAt).getTime();
    const createdAt = new Date(session.createdAt).getTime();
    const ttlMs = expiresAt - createdAt;
    // Should be approximately 120 seconds (allow some tolerance)
    expect(ttlMs).toBeGreaterThan(110_000);
    expect(ttlMs).toBeLessThan(130_000);
  });
});
```

