import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import {
  getSandboxTestContext,
  isSandboxAvailable,
  type SandboxTestContext,
} from './_helpers/sandbox-context';

const SANDBOX_AVAILABLE = isSandboxAvailable();
const TOOL_PACKAGE = '@tpmjs/official-sandbox-shell';
const TOOL_VERSION = '0.1.0';

describe.skipIf(!SANDBOX_AVAILABLE)('Sandbox Server — Isolation & Git', () => {
  let ctx: SandboxTestContext;

  beforeAll(() => {
    ctx = getSandboxTestContext();
  });

  afterAll(async () => {
    await ctx.cleanup();
  });

  describe('Session isolation', () => {
    it('should keep workspaces separate between sessions', async () => {
      const session1 = ctx.uniqueSessionId('iso-1');
      const session2 = ctx.uniqueSessionId('iso-2');
      ctx.trackSession(session1);
      ctx.trackSession(session2);

      await ctx.client.createSession(session1);
      await ctx.client.createSession(session2);

      // Write a file in session 1
      await ctx.client.executeTool({
        packageName: TOOL_PACKAGE,
        name: 'writeFile',
        version: TOOL_VERSION,
        params: { path: 'session1-only.txt', content: 'session 1 data' },
        sessionId: session1,
      });

      // Session 2 should NOT see session 1's file
      const listResult = await ctx.client.executeTool({
        packageName: TOOL_PACKAGE,
        name: 'listFiles',
        version: TOOL_VERSION,
        params: {},
        sessionId: session2,
      });

      expect(listResult.success).toBe(true);
      const entries = (listResult.output as { entries: Array<{ name: string }> }).entries;
      const names = entries.map((e) => e.name);
      expect(names).not.toContain('session1-only.txt');
    });
  });

  describe('Git operations', () => {
    let gitSessionId: string;

    beforeAll(async () => {
      gitSessionId = ctx.uniqueSessionId('git');
      ctx.trackSession(gitSessionId);
      await ctx.client.createSession(gitSessionId);
    });

    it('should clone a public repository', async () => {
      const result = await ctx.client.executeTool({
        packageName: TOOL_PACKAGE,
        name: 'shellExec',
        version: TOOL_VERSION,
        params: {
          command: 'git clone https://github.com/octocat/Hello-World.git --depth 1',
          timeout: 60000,
        },
        sessionId: gitSessionId,
      });

      expect(result.success).toBe(true);
      const output = result.output as { exitCode: number };
      expect(output.exitCode).toBe(0);

      // Verify cloned files exist
      const listResult = await ctx.client.executeTool({
        packageName: TOOL_PACKAGE,
        name: 'listFiles',
        version: TOOL_VERSION,
        params: { path: 'Hello-World' },
