      expect(listResult.success).toBe(true);
      const entries = (listResult.output as { entries: Array<{ name: string }> }).entries;
      const names = entries.map((e) => e.name);
      expect(names).toContain('README');
    }, 90_000); // Generous timeout for git clone

    it('should init a repo and commit', async () => {
      const commands = [
        'mkdir test-repo && cd test-repo',
        'git init',
        'git config user.email "test@ci.com"',
        'git config user.name "CI Bot"',
